HSK5_STORIES_40 = [
    (11, '现代都市的绿色出行', 'Giao thông xanh nơi đô thị hiện đại', 'urban_life', 'Đô thị & Môi trường', '🚲', 5, 'Xu hướng sử dụng xe đạp công cộng và xe điện giúp giảm tắc nghẽn và khí thải tại các thành phố lớn.', [('随着城市化进程的加速推进，交通拥堵与空气污染成为了许多大城市的普遍难题。', 'Suízhe chéngshìhuà jìnchéng de jiāsù tuījìn, jiāotōng yōngdǔ yǔ kōngqì wūrǎn chéngwéi le xǔduō dà chéngshì de pǔbiàn nántí.', 'Cùng với sự gia tăng nhanh chóng của tiến trình đô thị hóa, ùn tắc giao thông và ô nhiễm không khí đã trở thành vấn nạn phổ biến của nhiều đô thị lớn.'), ('为了倡导低碳环保的生活方式，越来越多的市民开始选择骑共享单车或乘坐公共交通出行。', 'Wèile chàngdǎo dītàn huánbǎo de shēnghuó fāngshì, yuè lái yuè duō de shìmín kāishǐ xuǎnzé qí gòngxiǎng dānchē huò chéngzuò gōnggòng jiāotōng chūxíng.', 'Nhằm khuyến khích lối sống carbon thấp và bảo vệ môi trường, ngày càng nhiều người dân lựa chọn đạp xe công cộng hoặc đi phương tiện công cộng.'), ('许多城市还在主要道路两侧规划了专门的非机动车道，为绿色出行提供了安全保障。', 'Xǔduō chéngshì hái zài zhǔyào dàolù liǎngcè guīhuà le zhuānmén de fēijīdòngchē dào, wèi lǜsè chūxíng tígōng le ānquán bǎozhàng.', 'Nhiều thành phố còn quy hoạch làn đường riêng cho phương tiện thô sơ ở hai bên các trục đường chính, bảo đảm an toàn cho việc di chuyển xanh.'), ('这种出行选择不仅有效缓解了上下班高峰期的拥堵，还让人们在通勤途中得到了身体锻炼。', 'Zhè zhǒng chūxíng xuǎnzé bùjǐn yǒuxiào huǎnjiě le shàngxiàbān gāofēngqī de yōngdǔ, hái ràng rénmen zài tōngqín túzhōng dédào le shēntǐ duànliàn.', 'Lựa chọn đi lại này không chỉ giảm thiểu hiệu quả tình trạng tắc đường giờ cao điểm mà còn giúp mọi người rèn luyện thể chất trên đường đi làm.'), ('绿色出行不仅关乎环境的改善，更是现代都市居民文明素养提升的生动体现。', 'Lǜsè chūxíng bùjǐn guānhū huánjìng de gǎishàn, gèng shì xiàndài chéngshì jūmín wénmíng sùyǎng tíshēng de shēngdòng tǐxiàn.', 'Giao thông xanh không chỉ liên quan đến cải thiện môi trường mà còn là minh chứng sống động cho sự nâng cao ý thức văn minh của cư dân đô thị hiện đại.')], [('Vấn đề phổ biến tại nhiều đô thị lớn được nhắc đến là gì?', ['Ùn tắc giao thông và ô nhiễm không khí', 'Thiếu hụt trường học', 'Giá cả hàng hóa tăng cao'], 0, 'Trong bài có câu: 交通拥堵与空气污染成为了许多大城市的普遍难题.'), ('Biện pháp nào được các thành phố triển khai để bảo đảm an toàn cho người đạp xe?', ['Cấm hoàn toàn ô tô', 'Quy hoạch làn đường riêng cho phương tiện thô sơ', 'Tăng tốc độ tối đa của xe máy'], 1, 'Trong câu có viết: 规划了专门的非机动车道，为绿色出行提供了安全保障.'), ('Lợi ích kép của việc lựa chọn giao thông xanh là gì?', ['Chỉ có lợi cho môi trường', 'Giảm tắc đường và rèn luyện thể chất trên đường đi', 'Tiết kiệm tiền mua nhà'], 1, 'Trong câu có viết: 有效缓解了拥堵，还让人们在通勤途中得到了身体锻炼.')]),
    (12, '职场沟通与倾听的艺术', 'Nghệ thuật giao tiếp và lắng nghe nơi công sở', 'communication', 'Kỹ năng công sở', '💼', 5, 'Lắng nghe chân thành và thấu hiểu góc nhìn của đồng nghiệp là chìa khóa xây dựng môi trường làm việc hiệu quả.', [('在快节奏的现代职场中，高效顺畅的沟通往往是团队取得成功的关键基石。', 'Zài kuài jiézòu de xiàndài zhíchǎng zhōng, gāoxiào shùnchàng de gōutōng wǎngwǎng shì tuánduì qǔdé chénggōng de guānjiàn jīshí.', 'Nơi công sở hiện đại nhịp độ nhanh, giao tiếp hiệu quả và suôn sẻ thường là nền tảng then chốt dẫn tới thành công của đội ngũ.'), ('许多人在交流时急于表达自己的观点，却常常忽略了认真倾听对方的真实想法。', 'Xǔduō rén zài jiāoliú shí jíyú biǎodá zìjǐ de guāndiǎn, què chángcháng hūlüè le rènzhēn qīngtīng duìfāng de zhēnshí xiǎngfǎ.', 'Nhiều người khi trao đổi thường nóng vội bày tỏ quan điểm của mình mà lơ là việc lắng nghe chân thành suy nghĩ thực sự của đối phương.'), ('真正懂得沟通的人，善于站在他人的立场思考问题，并给予及时而真诚的反馈。', 'Zhēnzhèng dǒngde gōutōng de rén, shànyú zhàn zài tārén de lìchǎng sīkǎo wèntí, bìng jǐyǔ jíshí ér zhēnchéng de fǎnkuì.', 'Người thực sự thấu hiểu nghệ thuật giao tiếp sẽ khéo léo đứng trên lập trường người khác để suy xét và phản hồi kịp thời, chân thành.'), ('清晰明确的表达配合耐心的倾听，能够有效避免误解，显著降低团队的协作成本。', 'Qīngxī míngquè de biǎodá pèihé nàixīn de qīngtīng, nénggòu yǒuxiào bìmiǎn wùjiě, xiǎnzhù jiàngdī tuánduì de xiézuò chéngběn.', 'Diễn đạt khúc chiết rõ ràng kết hợp với sự kiên nhẫn lắng nghe có thể tránh hiểu lầm hiệu quả và giảm đáng kể chi phí phối hợp.'), ('建立开放包容的交流氛围，才能激发出每位员工的创造潜力，推动企业持续发展。', 'Jiànlì kāifàng bāoróng de jiāoliú fēnwéi, cái néng jīfā chū měi wèi yuángōng de chuàngzào qiánlì, tuīdòng qǐyè chíxù fāzhǎn.', 'Xây dựng bầu không khí cởi mở bao dung mới có thể khơi dậy tiềm năng sáng tạo của từng nhân viên, thúc đẩy doanh nghiệp phát triển bền vững.')], [('Sai lầm phổ biến của nhiều người khi giao tiếp nơi làm việc là gì?', ['Nói quá nhỏ', 'Nóng vội bày tỏ ý mình mà quên lắng nghe người khác', 'Không chịu họp hành'], 1, 'Trong bài có câu: 急于表达自己的观点，却常常忽略了认真倾听对方的真实想法.'), ('Yếu tố nào giúp giảm chi phí cộng tác và tránh hiểu lầm trong nhóm?', ['Làm việc độc lập hoàn toàn', 'Diễn đạt rõ ràng kết hợp lắng nghe kiên nhẫn', 'Chỉ gửi email không nói chuyện'], 1, 'Trong câu có viết: 清晰明确的表达配合耐心的倾听，能够有效避免误解.'), ('Môi trường giao tiếp cởi mở mang lại giá trị gì cho doanh nghiệp?', ['Khơi dậy tiềm năng sáng tạo của nhân viên và phát triển bền vững', 'Giúp tăng giờ làm việc', 'Hạn chế tranh luận'], 0, 'Trong câu cuối có viết: 激发出每位员工的创造潜力，推动企业持续发展.')]),
    (13, '传统茶道与心境修养', 'Trà đạo truyền thống và tu dưỡng tâm tính', 'oriental_culture', 'Văn hóa truyền thống', '🍵', 5, 'Nghệ thuật pha trà và thưởng trà giúp con người tìm về sự an tĩnh và thanh lọc tâm hồn giữa bộn bề cuộc sống.', [('中国茶文化历史悠久，品茶不仅是一种生活习惯，更是一种陶冶情操的心灵修养。', 'Zhōngguó chá wénhuà lìshǐ yōujiǔ, pǐnchá bùjǐn shì yì zhǒng shēnghuó xíguàn, gèng shì yì zhǒng táoyě qíngcāo de xīnlíng xiūyǎng.', 'Văn hóa trà Trung Hoa có lịch sử lâu đời, thưởng trà không chỉ là một thói quen sinh hoạt mà còn là sự tu dưỡng tâm hồn để bồi đắp tính tình.'), ('从选茶、煮水到冲泡的每一个环节，都需要全神贯注，讲究从容不迫的节奏。', 'Cóng xuǎnchá, zhǔshuǐ dào chōngpào de měi yí gè huánjié, dōu xūyào quánshén-guànzhù, jiǎngjiu cóngróng-bùpò de jiézòu.', 'Từ chọn trà, đun nước cho đến hãm trà, mỗi khâu đều đòi hỏi sự tập trung cao độ và phong thái ung dung điềm đạm.'), ('在氤氲的茶香中，人们得以暂时放下世俗的烦恼与焦虑，体会内心的宁静与清明。', 'Zài yīnyūn de cháxiāng zhōng, rénmen déyǐ zànshí fàngxià shìsú de fánnǎo yǔ jiāolǜ, tǐhuì nèixīn de níngjìng yǔ qīngmíng.', 'Trong làn hương trà thoang thoảng, con người có thể tạm gác lại muộn phiền âu lo thế tục, cảm nhận sự an tĩnh và sáng tỏ trong tâm.'), ('茶道所蕴含的和敬清寂理念，启发我们在纷繁复杂的现代世界中保持淡泊与纯粹。', 'Chádào suǒ yùnhán de hé jìng qīng jì lǐniàn, qǐfā wǒmen zài fēnfán fùzá de xiàndài shìjiè zhōng bǎochí dànbó yǔ chúncuì.', 'Triết lý hòa - kính - thanh - tịnh trong trà đạo khơi gợi chúng ta giữ gìn sự đạm bạc và thuần khiết giữa thế giới hiện đại bộn bề.'), ('一杯清茶，承载着古人的生活美学，也为现代人构筑了一片安宁的精神绿洲。', 'Yì bēi qīngchá, chéngzài zhe gǔrén de shēnghuó měixué, yě wèi xiàndàirén gòuzhù le yí piàn ānníng de jīngshén lǜzhōu.', 'Một chén trà thanh đạm chứa đựng mỹ học đời sống của tiền nhân, đồng thời kiến tạo một ốc đảo tinh thần an lành cho người hiện đại.')], [('Pha trà đòi hỏi người thực hiện phải có thái độ và phong thái thế nào?', ['Vội vàng làm cho nhanh', 'Tập trung cao độ và giữ nhịp điệu ung dung điềm đạm', 'Tùy tiện thế nào cũng được'], 1, 'Trong bài có câu: 需要全神贯注，讲究从容不迫的节奏.'), ('Hương trà thoang thoảng giúp người thưởng thức đạt được trạng thái tâm lý gì?', ['Tạm gác lại phiền não và cảm nhận sự an tĩnh nội tâm', 'Cảm thấy hưng phấn tột độ', 'Quên hết công việc'], 0, 'Trong câu có viết: 暂时放下世俗的烦恼与焦虑，体会内心的宁静与清明.'), ('Một chén trà xanh mang lại giá trị biểu tượng nào cho cuộc sống hôm nay?', ['Là món đồ uống xa xỉ', 'Là ốc đảo tinh thần bình an chứa đựng mỹ học cổ nhân', 'Chỉ để giải khát thông thường'], 1, 'Trong câu cuối có viết: 承载着古人的生活美学，也为现代人构筑了一片安宁的精神绿洲.')]),
    (14, '智能家居改变日常生活', 'Nhà thông minh thay đổi cuộc sống thường nhật', 'smart_home', 'Công nghệ đời sống', '🏠', 5, 'Thiết bị kết nối Internet vạn vật mang lại sự tiện nghi, an toàn và tối ưu hóa năng lượng cho tổ ấm hiện đại.', [('物联网技术的快速普及，使得智能家居设备正在逐步走进寻常百姓的生活之中。', 'Wùliánwǎng jìshù de kuàisù pǔjí, shǐde zhìnéng jiājū shèbèi zhèngzài zhúbù zǒujìn xúncháng bǎixìng de shēnghuó zhī zhōng.', 'Sự phổ cập nhanh chóng của công nghệ Internet vạn vật đang đưa các thiết bị nhà thông minh từng bước đi vào đời sống của người dân bình thường.'), ('主人只需通过手机应用程序或者语音指令，就能轻松控制室内的灯光、温度与安防系统。', 'Zhǔrén zhǐ xū tōngguò shǒujī yìngyòng chéngxù huòzhě yǔyīn zhǐlìng, jiù néng qīngsōng kòngzhì shìnèi de dēngguāng, wēndù yǔ ānfáng xìtǒng.', 'Gia chủ chỉ cần thông qua ứng dụng di động hoặc khẩu lệnh giọng nói là có thể dễ dàng điều khiển ánh sáng, nhiệt độ và hệ thống an ninh trong phòng.'), ('智能传感器能够根据环境变化自动调节电器的运行状态，从而实现显著的节能效果。', "Zhìnéng chuángǎnqì nénggòu gēnjù huánjìng biànhuà zìdòng tiáojié diànqì de yùnxíng zhuàngtài, cóng'ér shíxiàn xiǎnzhù de jiénéng xiàoguǒ.", 'Cảm biến thông minh có thể tự động điều chỉnh trạng thái vận hành của đồ điện theo biến đổi môi trường, từ đó đạt hiệu quả tiết kiệm điện rõ rệt.'), ('即使出差在外，人们也能随时查看家中的安全监控，极大地增强了生活的安全感。', 'Jíshǐ chūchāi zài wài, rénmen yě néng suíshí chákàn jiāzhōng de ānquán jiānkòng, jídà de zēngqiáng le shēnghuó de ānquángǎn.', 'Ngay cả khi đi công tác xa, mọi người vẫn có thể theo dõi camera an ninh trong nhà bất cứ lúc nào, tăng cường đáng kể cảm giác an tâm.'), ('科技的不断进步让家庭空间更加人性化与智能化，为现代人带来了前所未有的舒适体验。', 'Kējì de búduàn jìnbù ràng jiātíng kōngjiān gèngjiā rénxìnghuà yǔ zhìnénghuà, wèi xiàndàirén dàilái le qiánsuǒwèiyǒu de shūshì tǐyàn.', 'Sự tiến bộ không ngừng của công nghệ làm cho không gian gia đình thêm phần nhân văn và thông minh, mang lại trải nghiệm tiện nghi chưa từng có.')], [('Người dùng có thể điều khiển thiết bị thông minh trong nhà bằng cách nào?', ['Phải gạt công tắc thủ công', 'Qua ứng dụng điện thoại hoặc khẩu lệnh giọng nói', 'Chờ thiết bị tự khởi động'], 1, 'Trong bài có câu: 通过手机应用程序或者语音指令，就能轻松控制.'), ('Cảm biến thông minh giúp ích gì cho gia đình?', ['Làm tăng lượng điện tiêu thụ', 'Tự điều chỉnh trạng thái vận hành để tiết kiệm năng lượng', 'Tắt toàn bộ hệ thống'], 1, 'Trong câu có viết: 自动调节电器的运行状态，从而实现显著的节能效果.'), ('Tác dụng của camera an ninh khi chủ nhà đi vắng là gì?', ['Cho phép kiểm tra an toàn từ xa và tăng cảm giác an tâm', 'Báo động giả liên tục', 'Tốn bộ nhớ điện thoại'], 0, 'Trong câu có viết: 随时查看家中的安全监控，极大地增强了生活的安全感.')]),
    (15, '终身学习时代的知识管理', 'Quản lý tri thức trong thời đại học tập suốt đời', 'education', 'Giáo dục & Trí tuệ', '📚', 5, 'Xây dựng hệ thống tri thức cá nhân và chọn lọc thông tin chất lượng cao để duy trì năng lực cạnh tranh lâu dài.', [('在信息飞速更新的现代社会，大学毕业并不意味着学习生涯的终结，而是一个全新的开端。', 'Zài xìnxī fēisù gēngxīn de xiàndài shèhuì, dàxué bìyè bìng bù yìwèizhe xuéxí shēngyá de zhōngjié, ér shì yí gè quánxīn de kāiduān.', 'Trong xã hội hiện đại thông tin cập nhật từng ngày, tốt nghiệp đại học không đồng nghĩa với kết thúc học tập mà là một khởi đầu hoàn toàn mới.'), ('面对浩如烟海的网络资源，建立科学的个人知识管理系统显得至关重要。', 'Miànduì hàorúyānhǎi de wǎngluò zīyuán, jiànlì kēxué de gèrén zhīshi guǎnlǐ xìtǒng xiǎnde zhìguān-zhòngyào.', 'Đứng trước nguồn tài nguyên mạng bao la như biển, xây dựng một hệ thống quản lý tri thức cá nhân khoa học trở nên vô cùng trọng yếu.'), ('我们应当学会筛选有价值的专业文献，并将其分类整理、定期复习与实践应用。', 'Wǒmen yīngdāng xuéhuì shāixuǎn yǒu jiàzhí de zhuānyè wénxiàn, bìng jiāng qí fēnlèi zhěnglǐ, dìngqī fùxí yǔ shíjiàn yìngyòng.', 'Chúng ta nên học cách chắt lọc tài liệu chuyên môn có giá trị, phân loại sắp xếp, định kỳ ôn tập và ứng dụng vào thực tế.'), ('只有把零散的信息转化为结构化的认知体系，知识才能真正转化为个人的核心竞争力。', 'Zhǐyǒu bǎ língsǎn de xìnxī zhuǎnhuà wéi jiégòuhuà de rènzhī tǐxì, zhīshi cái néng zhēnzhèng zhuǎnhuà wéi gèrén de héxīn jìngzhēnglì.', 'Chỉ khi chuyển hóa thông tin rời rạc thành hệ thống nhận thức có cấu trúc, tri thức mới thực sự biến thành năng lực cạnh tranh cốt lõi.'), ('持之以恒地扩充知识边界，我们才能在充满不确定性的未来世界中立于不败之地。', 'Chízhīyǐhéng de kuòchōng zhīshi biānjiè, wǒmen cái néng zài chōngmǎn bùquèdìngxìng de wèilái shìjiè zhōng lì yú búbài zhī dì.', 'Bền bỉ mở rộng ranh giới tri thức, chúng ta mới có thể đứng vững trước một thế giới tương lai đầy những bất định.')], [('Thời điểm tốt nghiệp đại học được tác giả nhìn nhận như thế nào?', ['Là điểm dừng của việc học', 'Là khởi đầu mới cho hành trình học tập suốt đời', 'Không còn quan trọng'], 1, 'Trong câu đầu có viết: 并不意味着学习生涯的终结，而是一个全新的开端.'), ('Cách thức hiệu quả để quản lý tri thức cá nhân là gì?', ['Lưu lại tất cả nhưng không đọc', 'Chọn lọc tài liệu giá trị, phân loại và đưa vào thực hành', 'Chỉ dựa vào trí nhớ'], 1, 'Trong bài có câu: 筛选有价值的专业文献，并将其分类整理、定期复习与实践应用.'), ('Làm thế nào để thông tin biến thành năng lực cạnh tranh cốt lõi?', ['Chuyển thông tin vụn vặt thành hệ thống nhận thức có cấu trúc', 'Đọc thật nhiều tin tức giật gân', 'Học vẹt thuộc lòng'], 0, 'Trong câu có viết: 把零散的信息转化为结构化的认知体系，知识才能真正转化为核心竞争力.')]),
    (16, '电子商务重塑乡村经济', 'Thương mại điện tử tái cấu trúc kinh tế nông thôn', 'rural_ecommerce', 'Kinh tế & Đổi mới', '🌾', 5, 'Mạng Internet và phát sóng trực tiếp mở ra kênh tiêu thụ nông sản rộng lớn, thúc đẩy hồi sinh làng quê.', [('互联网技术的深入普及，为中国偏远乡村的经济振兴注入了强大的发展生机。', 'Hùliánwǎng jìshù de shēnrù pǔjí, wèi Zhōngguó piānyuǎn xiāngcūn de jīngjì zhènxīng zhùrù le qiángdà de fāzhǎn shēngjī.', 'Sự phổ cập sâu rộng của công nghệ Internet đã tiếp thêm sinh khí phát triển mạnh mẽ cho công cuộc chấn hưng kinh tế nông thôn xa xôi.'), ('许多年轻村民借助网络直播平台，向全国各地的消费者推介家乡优质的绿色农产品。', 'Xǔduō niánqīng cūnmín jièzhù wǎngluò zhíbō píngtái, xiàng quánguó gèdì de xiāofèizhě tuījiè jiāxiāng yōuzhì de lǜsè nóngchǎnpǐn.', 'Nhiều thanh niên trong làng nhờ vào các nền tảng phát sóng trực tiếp để giới thiệu nông sản sạch chất lượng của quê hương tới người tiêu dùng cả nước.'), ('完善的农村物流网络消除了传统产销中间环节，使得新鲜瓜果能以最快速度送达餐桌。', 'Wánshàn de nóngcūn wùliú wǎngluò xiāochú le chuántǒng chǎnxiāo zhōngjiān huánjié, shǐde xīnxiān guāguǒ néng yǐ zuì kuài sùdù sòngdá cānzhuō.', 'Mạng lưới vận chuyển nông thôn hoàn thiện xóa bỏ các khâu trung gian truyền thống, giúp hoa quả tươi ngon đến bàn ăn với tốc độ nhanh nhất.'), ('这种直销模式不仅大幅增加了农民的家庭收入，还吸引了许多外出打工的青年返乡创业。', 'Zhè zhǒng zhíxiāo móshì bùjǐn dàfú zēngjiā le nóngmín de jiātíng shōurù, hái xīyǐn le xǔduō wàichū dǎgōng de qīngnián fǎnxiāng chuàngyè.', 'Mô hình bán trực tiếp này không chỉ tăng thu nhập đáng kể cho nông dân mà còn thu hút nhiều thanh niên đi làm xa trở về quê lập nghiệp.'), ('数字经济与乡村产业的紧密结合，正在描绘出一幅充满希望与活力的乡村振兴蓝图。', 'Shùzì jīngjì yǔ xiāngcūn chǎnyè de jǐnmì jiéhé, zhèngzài miáohuì chū yì fú chōngmǎn xīwàng yǔ huólì de xiāngcūn zhènxīng lántú.', 'Sự kết hợp chặt chẽ giữa kinh tế số và nông nghiệp đang vẽ nên một bức tranh chấn hưng nông thôn tràn đầy hy vọng và sức sống.')], [('Thanh niên nông thôn sử dụng công cụ gì để quảng bá nông sản sạch?', ['Phát tờ rơi ở bến xe', 'Nền tảng phát sóng trực tiếp (livestream) trên mạng', 'Chờ thương lái đến thu mua'], 1, 'Trong bài có câu: 借助网络直播平台，向全国各地的消费者推介家乡优质的绿色农产品.'), ('Lợi ích của mạng lưới vận tải nông thôn hoàn thiện là gì?', ['Xóa bỏ khâu trung gian, đưa hoa quả tươi tới người tiêu dùng nhanh nhất', 'Tăng thêm các trạm thu phí', 'Kéo dài thời gian giao hàng'], 0, 'Trong câu có viết: 消除了传统产销中间环节，使得新鲜瓜果能以最快速度送达餐桌.'), ('Hiệu ứng tích cực đối với nguồn nhân lực nông thôn là gì?', ['Thanh niên bỏ làng đi hết', 'Thu hút nhiều người trẻ đi làm ăn xa trở về khởi nghiệp', 'Giảm số lượng nông dân'], 1, 'Trong câu có viết: 吸引了许多外出打工的青年返乡创业.')]),
    (17, '保护非物质文化遗产', 'Bảo tồn di sản văn hóa phi vật thể', 'heritage', 'Di sản văn hóa', '🎭', 5, 'Gìn giữ và truyền dạy các làn điệu dân gian, nghề thủ công bí truyền để hồn cốt văn hóa sống mãi cùng thời gian.', [('非物质文化遗产是一个民族历史记忆与文化认同的生动载体，具有不可替代的价值。', 'Fēiwùzhì wénhuà yíchǎn shì yí gè mínzú lìshǐ jìyì yǔ wénhuà rèntóng de shēngdòng zàitǐ, jùyǒu bùkě-tìdài de jiàzhí.', 'Di sản văn hóa phi vật thể là vật mang sống động của ký ức lịch sử và bản sắc văn hóa dân tộc, mang giá trị không thể thay thế.'), ('剪纸、皮影戏和古法刺绣等传统技艺，凝聚着历代民间艺人的心血与智慧。', 'Jiǎnzhǐ, píyǐngxì hé gǔfǎ cìxiù děng chuántǒng jìyì, níngjù zhe lìdài mínjiān yìrén de xīnxuè yǔ zhìhuì.', 'Các kỹ nghệ truyền thống như cắt giấy, múa rối bóng và thêu cổ truyền đúc kết tâm huyết và trí tuệ của các nghệ nhân dân gian qua nhiều thế hệ.'), ('然而在现代流行文化的冲击下，许多古老的手工艺正面临后继乏人的严峻危机。', "Rán'ér zài xiàndài liúxíng wénhuà de chōngjī xià, xǔduō gǔlǎo de shǒugōngyì zhèng miànlín hòujì-fárén de yánjùn wēijī.", 'Thế nhưng trước sự va đập của văn hóa đại chúng hiện đại, nhiều nghề thủ công cổ xưa đang đối mặt khủng hoảng thiếu người kế tục gay gắt.'), ('为了打破传承困境，许多传承人走进校园开办讲座，并将传统元素融入现代文创产品中。', 'Wèile dǎpò chuánchéng kùnjìng, xǔduō chuánchéngrén zǒujìn xiàoyuán kāibàn jiǎngzuò, bìng jiāng chuántǒng yuánsù róngrù xiàndài wénchuàng chǎnpǐn zhōng.', 'Để phá vỡ thế khó trong truyền nghề, nhiều nghệ nhân đã vào trường học giảng dạy và lồng ghép yếu tố truyền thống vào các sản phẩm sáng tạo văn hóa hiện đại.'), ('唤醒年轻一代对传统文化的热爱，才能让古老的非遗技艺在时光长河中生生不息。', "Huànxǐng niánqīng yídài duì chuántǒng wénhuà de rè'ài, cái néng ràng gǔlǎo de fēiyí jìyì zài shíguāng chánghé zhōng shēngshēng-bùxī.", 'Đánh thức tình yêu văn hóa truyền thống của thế hệ trẻ mới có thể giúp các kỹ nghệ di sản cổ xưa trường tồn cùng dòng chảy thời gian.')], [('Khó khăn lớn nhất mà các nghề thủ công truyền thống đang gặp phải là gì?', ['Thiếu nguyên liệu sản xuất', 'Nguy cơ thiếu người trẻ kế tục nghề truyền thống', 'Không ai biết cắt giấy'], 1, 'Trong bài có câu: 许多古老的手工艺正面临后继乏人的严峻危机.'), ('Các nghệ nhân đã làm gì để giải quyết thế bế tắc trong việc truyền dạy?', ['Đóng cửa không dạy ai', 'Vào trường học mở bài giảng và đưa nét truyền thống vào đồ sáng tạo hiện đại', 'Bỏ nghề chuyển sang làm việc khác'], 1, 'Trong câu có viết: 走进校园开办讲座，并将传统元素融入现代文创产品中.'), ('Yếu tố cốt lõi để duy trì sức sống của di sản văn hóa phi vật thể là gì?', ['Đánh thức niềm đam mê của thế hệ trẻ đối với văn hóa dân tộc', 'Chỉ lưu trữ trong sách vở', 'Phụ thuộc vào viện trợ quốc tế'], 0, 'Trong câu cuối có viết: 唤醒年轻一代对传统文化的热爱，才能让古老的非遗技艺生生不息.')]),
    (18, '心理暗示与积极生活', 'Ám thị tâm lý và cuộc sống tích cực', 'psychology', 'Tâm lý học', '💡', 5, 'Sức mạnh của lời tự nhủ tích cực giúp vượt qua nỗi sợ hãi và khơi dậy tiềm năng tiềm ẩn trong mỗi con người.', [('心理暗示是一种潜在的心理机制，在不知不觉中深刻影响着人们的情绪与行为模式。', 'Xīnlǐ ànshì shì yì zhǒng qiánzài de xīnlǐ jīzhì, zài bùzhī-bùjué zhōng shēnkè yǐngxiǎng zhe rénmen de qíngxù yǔ xíngwéi móshì.', 'Ám thị tâm lý là một cơ chế tiềm thức sâu xa, âm thầm tác động sâu sắc đến trạng thái cảm xúc và mô thức hành vi của con người.'), ('如果我们经常在心中重复消极的评语，潜意识就会逐渐接受并削弱我们迎接挑战的勇气。', 'Rúguǒ wǒmen chángcháng zài xīnzhōng chóngfù xiāojí de píngyǔ, qiǎnyìshí jiù huì zhújiàn jiēshòu bìng xuēruò wǒmen yíngjiē tiǎozhàn de yǒngqì.', 'Nếu chúng ta thường xuyên lặp lại những lời tự phán xét tiêu cực trong lòng, tiềm thức sẽ dần chấp nhận và làm suy yếu lòng dũng cảm đương đầu thử thách.'), ('相反，学会给予自己真诚的积极暗示，能够有效缓解紧张情绪，增强战胜困难的信心。', 'Xiāngfǎn, xuéhuì jǐyǔ zìjǐ zhēnchéng de jījí ànshì, nénggòu yǒuxiào huǎnjiě jǐnzhāng qíngxù, zēngqiáng zhànshèng kùnnan de xìnxīn.', 'Ngược lại, học cách tự trao cho mình những ám thị tích cực chân thành có thể xua tan căng thẳng hiệu quả và củng cố niềm tin vượt qua khó khăn.'), ('每天早晨对着镜子微笑，给自己一句鼓舞的话语，往往能带来整天充沛的精神状态。', 'Měitiān zǎochén duì zhe jìngzi wēixiào, jǐ zìjǐ yí jù gǔwǔ de huàyǔ, wǎngwǎng néng dàilái zhěng tiān chōngpèi de jīngshén zhuàngtài.', 'Mỗi buổi sáng mỉm cười trước gương, gửi tới bản thân một câu khích lệ thường mang lại nguồn năng lượng tinh thần dồi dào suốt cả ngày.'), ('改变内心与自己的对话方式，是重塑自信心并迈向幸福人生的第一步。', 'Gǎibiàn nèixīn yǔ zìjǐ de duìhuà fāngshì, shì chóngsù zìxìnxīn bìng màixiàng xìngfú rénshēng de dì-yī bù.', 'Thay đổi cách đối thoại nội tâm với chính mình là bước đi đầu tiên để tái thiết lòng tự tin và bước tới cuộc đời hạnh phúc.')], [('Tác hại của việc thường xuyên tự phán xét tiêu cực là gì?', ['Làm tiềm thức suy yếu lòng can đảm vượt qua thử thách', 'Giúp con người thông minh hơn', 'Không có ảnh hưởng nào'], 0, 'Trong bài có câu: 潜意识就会逐渐接受并削弱我们迎接挑战的勇气.'), ('Hành động đơn giản mỗi buổi sáng nào giúp duy trì tinh thần hứng khởi?', ['Nhìn vào gương mỉm cười và nói lời cổ vũ bản thân', 'Than vãn về thời tiết', 'Ngủ nướng không dậy'], 0, 'Trong câu có viết: 对着镜子微笑，给自己一句鼓舞的话语，往往能带来整天充沛的精神状态.'), ('Bước đầu tiên để tái tạo lòng tự tin theo tác giả là gì?', ['Thay đổi cách đối thoại nội tâm với chính mình', 'Chờ đợi sự khen ngợi của người khác', 'Đổ lỗi cho hoàn cảnh'], 0, 'Trong câu cuối có viết: 改变内心与自己的对话方式，是重塑自信心的第一步.')]),
    (19, '极简主义生活方式', 'Lối sống tối giản trong kỷ nguyên tiêu dùng', 'minimalism', 'Phong cách sống', '🌿', 5, 'Giải phóng bản thân khỏi sự trói buộc của vật chất dư thừa để tập trung vào những giá trị tinh thần cốt lõi.', [('在物质极其充裕的今天，许多人发现过度的消费并不能带来持久的快乐，反而让人感到疲惫。', "Zài wùzhì jíqí chōngyù de jīntiān, xǔduō rén fāxiàn guòdù de xiāofèi bìng bù néng dàilái chíjiǔ de kuàilè, fǎn'ér ràng rén gǎndào píbèi.", 'Trong thời đại vật chất dồi dào hôm nay, nhiều người nhận ra tiêu dùng quá đà không mang lại niềm vui lâu dài mà trái lại còn khiến ta kiệt sức.'), ('极简主义倡导人们定期审视自己的生活空间，果断清理那些长期闲置的非必需品。', 'Jíjiǎn zhǔyì chàngdǎo rénmen dìngqī shěnshì zìjǐ de shēnghuó kōngjiān, guǒduàn qīnglǐ nàxiē chángqī xiánzhì de fēi bìxūpǐn.', 'Chủ nghĩa tối giản cổ vũ mọi người định kỳ xem xét không gian sống, kiên quyết dọn dẹp những đồ vật không thiết yếu bị bỏ xó bấy lâu.'), ('舍弃杂乱无章的外在物品，往往能帮助我们理清内心真正珍视的梦想与人际关系。', 'Shěqì záluàn-wúzhāng de wàizài wùpǐn, wǎngwǎng néng bāngzhù wǒmen lǐqīng nèixīn zhēnzhèng zhēnshì de mèngxiǎng yǔ rénjì guānxi.', 'Từ bỏ những đồ vật ngoài thân bừa bộn thường giúp ta soi sáng những ước mơ và mối quan hệ thực sự trân quý trong lòng.'), ('购买物品时追求精良耐用而非数量堆砌，是极简生活者普遍遵循的消费法则。', 'Gòumǎi wùpǐn shí zhuīqiú jīngliáng nàiyòng ér fēi shùliàng duīqì, shì jíjiǎn shēnghuózhě pǔbiàn zūnxún de xiāofèi fǎzé.', 'Khi mua sắm hướng tới chất lượng tinh xảo bền bỉ thay vì tích lũy số lượng là nguyên tắc tiêu dùng của người theo lối sống tối giản.'), ('化繁为简不仅是一种整理房间的技巧，更是一种回归本真、富足平静的心灵智慧。', 'Huà fán wéi jiǎn bùjǐn shì yì zhǒng zhěnglǐ fángjiān de jìqiǎo, gèng shì yì zhǒng huíguī běnzhēn, fùzú píngjìng de xīnlíng zhìhuì.', 'Biến phức tạp thành giản dị không chỉ là mẹo dọn phòng mà còn là trí tuệ tâm hồn tìm về sự thuần khiết, thanh tịnh và đủ đầy.')], [('Chủ nghĩa tối giản khuyên con người nên làm gì với đồ dùng cá nhân?', ['Mua thêm thật nhiều đồ giảm giá', 'Định kỳ dọn dẹp các vật dụng không thiết yếu để lâu ngày', 'Giữ tất cả mọi thứ'], 1, 'Trong bài có câu: 果断清理那些长期闲置的非必需品.'), ('Nguyên tắc mua sắm của người theo đuổi lối sống tối giản là gì?', ['Chú trọng đồ tinh xảo bền bỉ thay vì chạy theo số lượng', 'Cứ rẻ là mua nhiều', 'Không bao giờ mua bất cứ thứ gì'], 0, 'Trong câu có viết: 追求精良耐用而非数量堆砌.'), ('Ý nghĩa sâu sắc của việc đơn giản hóa cuộc sống là gì?', ['Chỉ để có căn phòng đẹp mắt', 'Trí tuệ tìm về bản ngã nguyên sơ, tĩnh lặng và an vui trong tâm', 'Tiết kiệm tiền mua xe'], 1, 'Trong câu cuối có viết: 是一种回归本真、富足平静的心灵智慧.')]),
    (20, '现代医疗中的预防哲学', 'Triết lý phòng bệnh trong y học hiện đại', 'medicine', 'Y tế & Sức khỏe', '🏥', 5, 'Khám sức khỏe định kỳ và duy trì lối sống lành mạnh là tấm lá chắn bảo vệ tốt nhất cho cơ thể.', [('传统观念往往将看病就医看作身体出现严重病痛后的被动补救措施。', 'Chuántǒng guānniàn wǎngwǎng jiāng kànbìng jiùyī kàn zuò shēntǐ chūxiàn yánzhòng bìngtòng hòu de bèidòng bǔjiù cuòshī.', 'Quan niệm truyền thống thường coi việc khám chữa bệnh là biện pháp khắc phục bị động sau khi cơ thể đã phát sinh đau ốm nghiêm trọng.'), ('现代医学则日益强调预防为主的健康理念，提倡在疾病发作前消灭隐患。', 'Xiàndài yīxué zé rìyì qiángdiào yùfáng wéi zhǔ de jiànkāng lǐniàn, tíchàng zài jíbìng fāzuò qián xiāomiè yǐnhuàn.', 'Y học hiện đại lại ngày càng nhấn mạnh triết lý sức khỏe phòng bệnh là chính, chủ trương triệt tiêu mầm mống trước khi bệnh bộc phát.'), ('定期进行全面的身体检查，能够及早发现潜藏的生理指标异常并采取干预手段。', 'Dìngqī jìnxíng quánmiàn de shēntǐ jiǎnchá, nénggòu jízǎo fāxiàn qiáncáng de shēnglǐ zhǐbiāo yìcháng bìng cǎiqǔ gānyù shǒuduàn.', 'Định kỳ khám sức khỏe tổng quát có thể phát hiện sớm các chỉ số sinh lý bất thường tiềm ẩn để kịp thời can thiệp.'), ('均衡合理的膳食搭配、适度规律的体育锻炼和乐观心态，是抵御疾病的最佳防线。', 'Jūnhéng hélǐ de shànshí dāpèi, shìdù guīlǜ de tǐyù duànliàn hé lèguān xīntài, shì dǐyù jíbìng de zuì jiā fángxiàn.', 'Chế độ ăn uống cân bằng, tập luyện thể thao điều độ và tâm thái lạc quan là phòng tuyến tốt nhất chống lại bệnh tật.'), ('投资于日常的健康管理，是对自己与家庭未来幸福最明智且负责任的保障。', 'Tóuzī yú rìcháng de jiànkāng guǎnlǐ, shì duì zìjǐ yǔ jiātíng wèilái xìngfú zuì míngzhì qiě fù-zérèn de bǎozhàng.', 'Đầu tư cho việc quản lý sức khỏe thường nhật là sự bảo đảm sáng suốt và có trách nhiệm nhất cho hạnh phúc tương lai của bản thân và gia đình.')], [('Sự khác biệt căn bản của y học hiện đại so với quan niệm truyền thống là gì?', ['Chỉ chữa khi bệnh đã nặng', 'Nhấn mạnh phòng ngừa từ sớm trước khi bệnh phát tác', 'Không dùng thuốc men'], 1, 'Trong bài có câu: 现代医学则日益强调预防为主的健康理念.'), ('Khám sức khỏe định kỳ mang lại lợi ích gì?', ['Phát hiện sớm chỉ số bất thường để can thiệp kịp thời', 'Gây tốn kém vô ích', 'Chỉ để lấy giấy chứng nhận'], 0, 'Trong câu có viết: 及早发现潜藏的生理指标异常并采取干预手段.'), ('Ba yếu tố tạo nên phòng tuyến tốt nhất chống lại bệnh tật gồm những gì?', ['Ăn kiêng khắc nghiệt, ngủ nhiều và dùng thuốc bổ', 'Dinh dưỡng cân đối, vận động điều độ và tâm thái lạc quan', 'Lao động nặng liên tục'], 1, 'Trong câu có viết: 均衡合理的膳食搭配、适度规律的体育锻炼和乐观心态.')]),
    (21, '团队协作与领导力提升', 'Hợp tác đồng đội và nâng cao năng lực lãnh đạo', 'management', 'Quản trị & Kỹ năng', '🤝', 5, 'Một nhà lãnh đạo xuất sắc biết phát huy thế mạnh của từng cá nhân và truyền cảm hứng để tập thể cùng vươn tới mục tiêu.', [('任何伟大的事业都不是单打独斗能够完成的，卓越的团队协作是成功的根本保障。', 'Rènhé wěidà de shìyè dōu bú shì dāndǎ-dúdòu nénggòu wánchéng de, zhuóyuè de tuánduì xiézuò shì chénggōng de gēnběn bǎozhàng.', 'Mọi sự nghiệp vĩ đại đều không thể hoàn thành bởi nỗ lực đơn độc, sự hợp tác đồng đội xuất chúng là bảo chứng căn bản cho thành công.'), ('优秀的领导者绝不仅仅是任务的分配者，更是愿景的描绘者与士气的激励者。', 'Yōuxiù de lǐngdǎozhě jué bù jǐnjǐn shì rènwù de fēnpèizhě, gèng shì yuànjǐng de miáohuìzhě yǔ shìqì de jīlìzhě.', 'Người lãnh đạo ưu tú tuyệt đối không đơn thuần là người phân chia công việc, mà là người phác thảo tầm nhìn và khích lệ sĩ khí.'), ('善于发现每位团队成员独特的专长与潜能，并安排在最合适的岗位上，是知人善任的体现。', 'Shànyú fāxiàn měi wèi tuánduì chéngyuán dútè de zhuāncháng yǔ qiánnéng, bìng ānpái zài zuì héshì de gǎngwèi shàng, shì zhīrén-shànrèn de tǐxiàn.', 'Biết nhận diện sở trường và tiềm năng độc đáo của từng thành viên để bố trí vào vị trí phù hợp nhất là biểu hiện của thuật dùng người.'), ('在面对困难与挫折时，领导者应当勇于承担责任，为团队成员提供坚强的后盾支持。', 'Zài miànduì kùnnan yǔ cuòzhé shí, lǐngdǎozhě yīngdāng yǒngyú chéngdān zérèn, wèi tuánduì chéngyuán tígōng jiānqiáng de hòudùn zhīchí.', 'Khi đối diện với gian khó và trở ngại, nhà lãnh đạo cần dũng cảm nhận trách nhiệm, làm chỗ dựa vững chắc cho các thành viên trong đội.'), ('互相信任、彼此支持的团队文化，能够迸发出无可限量的合力，创造惊人的业绩。', 'Hùxiāng xìnrèn, bǐcǐ zhīchí de tuánduì wénhuà, nénggòu bèngfā chū wúkě xiànliàng de hélì, chuàngzào jīngrén de yèjì.', 'Văn hóa đội ngũ tin tưởng và tương trợ lẫn nhau có thể bùng nổ sức mạnh cộng hưởng vô hạn, kiến tạo nên thành tích đáng kinh ngạc.')], [('Vai trò cốt lõi của người lãnh đạo ưu tú là gì?', ['Chỉ kiểm soát giờ giấc nhân viên', 'Phác thảo tầm nhìn và truyền cảm hứng khích lệ tinh thần', 'Làm hết mọi việc một mình'], 1, 'Trong bài có câu: 更是愿景的描绘者与士气的激励者.'), ("Hành động thể hiện nghệ thuật 'dùng người tài tình' (知人善任) là gì?", ['Giao việc ngẫu nhiên', 'Nhận diện sở trường và xếp đặt đúng vị trí phù hợp', 'Chỉ giao việc khó cho người mới'], 1, 'Trong câu có viết: 发现独特的专长与潜能，并安排在最合适的岗位上.'), ('Văn hóa nào giúp tập thể tạo nên kỳ tích và thành tựu vượt trội?', ['Cạnh tranh ngầm và ngờ vực lẫn nhau', 'Tin tưởng sâu sắc và tương trợ lẫn nhau', 'Làm việc độc lập không chia sẻ'], 1, 'Trong câu cuối có viết: 互相信任、彼此支持的团队文化，能够迸发出无可限量的合力.')]),
    (22, '中国传统书法的美学意蕴', 'Ý vị thẩm mỹ của thư pháp truyền thống Trung Hoa', 'calligraphy', 'Nghệ thuật & Thẩm mỹ', '🖌️', 5, 'Đường nét bút mực uyển chuyển thể hiện khí chất, tâm hồn và tư duy triết học sâu xa của người cầm bút.', [('中国传统书法艺术不仅仅是书写汉字的技巧，更是凝结东方哲学思想的精神图景。', 'Zhōngguó chuántǒng shūfǎ yìshù bù jǐnjǐn shì shūxiě hànzì de jìqiǎo, gèng shì níngjié dōngfāng zhéxué sīxiǎng de jīngshén tújǐng.', 'Nghệ thuật thư pháp truyền thống Trung Hoa không đơn thuần là kỹ xảo viết chữ Hán, mà là bức tranh tinh thần kết tinh tư tưởng triết học phương Đông.'), ('一笔一画之间的提按转折与干湿浓淡，生动展现了书写者当下的心境与情感起伏。', 'Yì bǐ yí huà zhījiān de tí àn zhuǎn zhé yǔ gān shī nóng dàn, shēngdòng zhǎnxiàn le shūxiězhě dāngxià de xīnjìng yǔ qínggǎn qǐfú.', 'Sự nhấn nhá, chuyển bút cùng sắc mực khô ướt đậm nhạt trong từng nét chữ phản ánh sống động tâm cảnh và xúc cảm của người cầm bút.'), ('练习书法要求心平气和、凝神聚气，长期的临摹创作能够有效磨砺个人的专注力与耐力。', 'Liànxí shūfǎ yāoqiú xīnpíng-qìhé, níngshén-jùqì, chángqī de línmó chuàngzuò nénggòu yǒuxiào mólì gèrén de zhuānzhùlì yǔ nàilì.', 'Luyện thư pháp đòi hỏi tâm bình khí hòa, tập trung tinh thần; sao chép sáng tác lâu dài có thể tôi luyện tính kiên nhẫn và khả năng tập trung.'), ('优秀的墨宝宛如无声的乐章，点线错落间充满了流动的节奏感与和谐的美感。', 'Yōuxiù de mòbǎo wǎnrú wúshēng de yuèzhāng, diǎn xiàn cuòluò jiān chōngmǎn le liúdòng de jiézòugǎn yǔ héxié de měigǎn.', 'Tác phẩm thư pháp xuất sắc tựa như bản nhạc không lời, các nét chấm phá đan xen tràn ngập nhịp điệu uyển chuyển và vẻ đẹp hài hòa.'), ('品鉴书法不仅是欣赏视觉形式，更是跨越时空与古代文人进行心灵相通的美妙体验。', 'Pǐnjiàn shūfǎ bùjǐn shì xīnshǎng shìjué xíngshì, gèng shì kuàyuè shíkōng yǔ gǔdài wénrén jìnxíng xīnlíng xiāngtōng de měimiào tǐyàn.', 'Thưởng lãm thư pháp không chỉ là ngắm nhìn hình thức thị giác mà còn là trải nghiệm giao cảm tâm hồn vượt không gian cùng các bậc văn nhân xưa.')], [('Nét mực đậm nhạt và chuyển hướng của ngọn bút phản ánh điều gì?', ['Giá tiền của cây bút', 'Tâm trạng và biến chuyển cảm xúc của người viết tại thời điểm đó', 'Chất lượng giấy vẽ'], 1, 'Trong bài có câu: 生动展现了书写者当下的心境与情感起伏.'), ('Lợi ích tâm lý của việc kiên trì luyện tập thư pháp là gì?', ['Rèn giũa khả năng tập trung và sự bền bỉ kiên nhẫn', 'Tập cho tay không mỏi', 'Giúp tăng tốc độ đánh máy'], 0, 'Trong câu có viết: 有效磨砺个人的专注力与耐力.'), ('Tác phẩm thư pháp đẹp được ví như điều gì trong bài viết?', ['Bức ảnh chụp tĩnh', 'Bản nhạc không lời tràn ngập nhịp điệu và vẻ đẹp hài hòa', 'Một cuốn sổ ghi chép'], 1, 'Trong câu có viết: 宛如无声的乐章，点线错落间充满了流动的节奏感与和谐的美感.')]),
    (23, '人与宠物的温情陪伴', 'Tình bạn ấm áp giữa con người và thú cưng', 'companion_pets', 'Đời sống & Thú cưng', '🐾', 5, 'Thú cưng không chỉ là bạn bốn chân mà còn mang lại sự an ủi tinh thần, giảm stress và bồi đắp lòng nhân ái.', [('在生活节奏加快的现代社会，饲养猫狗等伴侣宠物已成为许多家庭不可或缺的温暖元素。', 'Zài shēnghuó jiézòu jiākuài de xiàndài shèhuì, sìyǎng māo gǒu děng bànlǚ chǒngwù yǐ chéngwéi xǔduō jiātíng bùkě-huòquē de wēnnuǎn yuánsù.', 'Trong xã hội hiện đại nhịp sống hối hả, nuôi thú cưng đồng hành như chó mèo đã trở thành yếu tố ấm áp không thể thiếu của nhiều gia đình.'), ('无论主人在外面经历了多少烦心与疲惫，回到家看到宠物热情的摇尾迎接，内心的疲劳便瞬间消散。', 'Wúlùn zhǔrén zài wàimiàn jīnglì le duōshao fánxīn yǔ píbèi, huí dào jiā kàndào chǒngwù rèqíng de yáowěi yíngjiē, nèixīn de píláo biàn shùnjiān xiāosàn.', 'Dù chủ nhân ngoài kia trải qua bao mệt mỏi phiền muộn, khi về nhà thấy thú cưng vẫy đuôi đón chào nồng nhiệt, nhọc nhằn lập tức tan biến.'), ('科学研究证实，抚摸宠物能够促使人体分泌多巴胺，显著减轻心理焦虑并改善睡眠质量。', "Kēxué yánjiū zhèngshí, fǔmō chǒngwù nénggòu cùshǐ réntǐ fēnmì duōbā'àn, xiǎnzhù jiǎnqīng xīnlǐ jiāolǜ bìng gǎishàn shuìmián zhìliàng.", 'Nghiên cứu khoa học xác nhận rằng vuốt ve thú cưng kích thích cơ thể tiết dopamine, giảm đáng kể lo âu và cải thiện chất lượng giấc ngủ.'), ('照料宠物的饮食起居与日常健康，也让年轻人学会了承担责任，培养了细腻的爱心与耐心。', 'Zhàoliào chǒngwù de yǐnshí qǐjū yǔ rìcháng jiànkāng, yě ràng niánqīngrén xuéhuì le chéngdān zérèn, péiyǎng le xìnì de àixīn yǔ nàixīn.', 'Chăm lo việc ăn ngủ sinh hoạt thường ngày của thú cưng cũng giúp người trẻ học cách gánh vác trách nhiệm, bồi dưỡng sự kiên nhẫn và tình yêu thương.'), ('这种跨越物种的真挚情感交流，为城市生活中孤寂的灵魂带来了无微不至的抚慰与寄托。', 'Zhè zhǒng kuàyuè wùzhǒng de zhēnzhì qínggǎn jiāoliú, wèi chéngshì shēnghuó zhōng gūjì de línghún dàilái le wúwēi-bùzhì de fǔwèi yǔ jìtuō.', 'Sự giao lưu tình cảm chân thành vượt loài này mang đến niềm an ủi và chỗ dựa tinh thần chu đáo cho những tâm hồn cô đơn chốn thị thành.')], [('Hành động vẫy đuôi đón chào của thú cưng khi chủ về nhà mang lại tác dụng gì?', ['Làm chủ giật mình', 'Xua tan mệt mỏi và phiền muộn ngoài xã hội tức thì', 'Đòi ăn ngay lập tức'], 1, 'Trong bài có câu: 内心的疲劳便瞬间消散.'), ('Theo nghiên cứu khoa học, việc vuốt ve thú cưng đem lại lợi ích sinh lý nào?', ['Tăng nhịp tim đột ngột', 'Kích thích tiết dopamine, giảm lo âu và cải thiện giấc ngủ', 'Gây dị ứng da'], 1, 'Trong câu có viết: 促使人体分泌多巴胺，显著减轻心理焦虑并改善睡眠质量.'), ('Nuôi dưỡng thú cưng giúp người trẻ rèn luyện những đức tính nào?', ['Tính lười biếng', 'Học cách gánh vác trách nhiệm, có lòng yêu thương và tính kiên nhẫn', 'Sự xa hoa lãng phí'], 1, 'Trong câu có viết: 学会了承担责任，培养了细腻的爱心与耐心.')]),
    (24, '大数据时代的个人隐私', 'Bảo vệ thông tin cá nhân trong thời đại dữ liệu lớn', 'privacy', 'Công nghệ & Đời tư', '🔒', 5, 'Cân bằng giữa tiện ích số hóa và bảo mật thông tin cá nhân là thách thức lớn cần sự chung tay của pháp luật và công nghệ.', [('数字化技术的飞速普及极大地方便了人们的日常生活，但同时也对个人隐私保护带来了前所未有的考验。', 'Shùzìhuà jìshù de fēisù pǔjí jídà de fāngbiàn le rénmen de rìcháng shēnghuó, dàn tóngshí yě duì gèrén yǐnsī bǎohù dàilái le qiánsuǒwèiyǒu de kǎoyàn.', 'Sự phổ cập vũ bão của công nghệ số hóa tạo tiện lợi lớn cho sinh hoạt thường nhật, nhưng đồng thời đặt ra thử thách chưa từng thấy cho việc bảo vệ thông tin riêng tư.'), ('我们在浏览网页、手机购物以及使用社交软件时留下的数字足迹，常常被算法收集并精准分析。', 'Wǒmen zài liúlǎn wǎngyè, shǒujī gòuwù yǐjí shǐyòng shèjiāo ruǎnjiàn shí liúxià de shùzì zújì, chángcháng bèi suànfǎ shōují bìng jīngzhǔn fēnxī.', 'Dấu chân số chúng ta để lại khi lướt web, mua hàng qua điện thoại hay dùng mạng xã hội thường bị thuật toán thu thập và phân tích chuẩn xác.'), ('一旦个人敏感数据发生泄露，不仅会招致垃圾短信的骚扰，甚至可能遭遇电信网络诈骗的威胁。', 'Yídàn gèrén mǐngǎn shùjù fāshēng xièlòu, bùjǐn huì zhāozhì lājī duǎnxìn de sāorǎo, shènzhì kěnéng zāoyù diànxìn wǎngluò zhàpiàn de wēixié.', 'Một khi dữ liệu nhạy cảm cá nhân bị rò rỉ, không những chuốc lấy tin nhắn rác quấy rầy mà còn có thể đối mặt hiểm họa lừa đảo viễn thông mạng.'), ('提高公众的数据安全防范意识，不随意向陌生链接授权个人信息，是自我防护的第一道关卡。', 'Tígāo gōngzhòng de shùjù ānquán fángfàn yìshí, bù suíyì xiàng mòshēng liànjiē shòuquán gèrén xìnxī, shì zìwǒ fánghù de dì-yī dào guānkǎ.', 'Nâng cao ý thức phòng vệ an toàn dữ liệu, không tùy tiện cấp quyền thông tin cá nhân cho đường link lạ là chốt chặn bảo vệ bản thân đầu tiên.'), ('健全严格的法律法规与行业自律规范，才能在享受数字便利的同时切实筑牢隐私安全的防火墙。', 'Jiànquán yángé de fǎlǜ fǎguī yǔ hángyè zìlǜ guīfàn, cái néng zài xiǎngshòu shùzì biànlì de tóngshí qièshí zhù láo yǐnsī ānquán de fánghuǒqiáng.', 'Hoàn thiện luật pháp nghiêm minh và quy chuẩn tự quản của ngành mới có thể xây chắc bức tường lửa an toàn dữ liệu khi thụ hưởng tiện ích số.')], [('Dấu chân số của người dùng trên Internet thường bị các thuật toán làm gì?', ['Xóa bỏ ngay lập tức', 'Thu thập và phân tích chính xác hành vi', 'Bỏ qua không quan tâm'], 1, 'Trong bài có câu: 常常被算法收集并精准分析.'), ('Hậu quả nguy hiểm khi dữ liệu cá nhân bị rò rỉ là gì?', ['Không có ảnh hưởng gì', 'Bị tin nhắn rác quấy rầy và nguy cơ đối mặt với lừa đảo mạng', 'Điện thoại tự tắt nguồn'], 1, 'Trong câu có viết: 不仅会招致垃圾短信的骚扰，甚至可能遭遇电信网络诈骗的威胁.'), ('Biện pháp tự bảo vệ đầu tiên của mỗi cá nhân là gì?', ['Không dùng điện thoại nữa', 'Nâng cao cảnh giác và không tùy tiện cấp quyền thông tin cho link lạ', 'Công khai mật khẩu'], 1, 'Trong câu có viết: 提高公众的数据安全防范意识，不随意向陌生链接授权个人信息.')]),
    (25, '现代博物馆的公共教育', 'Chức năng giáo dục công cộng của bảo tàng hiện đại', 'museum_education', 'Bảo tàng & Giáo dục', '🏛️', 5, 'Bảo tàng ngày nay không chỉ là nơi lưu giữ cổ vật mà còn là lớp học tương tác khơi gợi trí tò mò cho mọi lứa tuổi.', [('在很多人的传统印象中，博物馆常常是摆放着玻璃展柜与陈旧古董的严肃肃穆之所。', 'Zài hěn duō rén de chuántǒng yìnxiàng zhōng, bówùguǎn chángcháng shì bǎifàng zhe bōli zhǎnguì yǔ chénjiù gǔdǒng de yánsù sùmù zhī suǒ.', 'Trong ấn tượng truyền thống của nhiều người, bảo tàng thường là nơi trang nghiêm tôn nghiêm với những tủ kính trưng bày đồ cổ xưa cũ.'), ('然而现代博物馆正在发生深刻转型，越来越重视自身的社会公共教育与互动体验功能。', "Rán'ér xiàndài bówùguǎn zhèngzài fāshēng shēnkè zhuǎnxíng, yuè lái yuè zhòngshì zìshēn de shèhuì gōnggòng jiàoyù yǔ hùdòng tǐyàn gōngnéng.", 'Thế nhưng các bảo tàng hiện đại đang chuyển mình sâu sắc, ngày càng chú trọng chức năng giáo dục cộng đồng và trải nghiệm tương tác.'), ('虚拟现实技术和数字化展板的引入，让参观者能够亲手操作并沉浸式感知历史事件的发生现场。', 'Xūnǐ xiànshí jìshù hé shùzìhuà zhǎnbǎn de yǐnrù, ràng cānguānzhě nénggòu qīnshǒu cāozuò bìng chénjìnshì gǎnzhī lìshǐ shìjiàn de fāshēng xiànchǎng.', 'Công nghệ thực tế ảo và bảng trưng bày số hóa giúp người tham quan có thể tự tay thao tác và cảm nhận hiện trường sự kiện lịch sử một cách chân thực.'), ('丰富多彩的青少年研学活动与科普讲座，激发了孩子们对探索科学和历史文化的浓厚兴趣。', 'Fēngfù-duōcǎi de qīngshàonián yánxué huódòng yǔ kēpǔ jiǎngzuò, jīfā le háizimen duì tànsuǒ kēxué hé lìshǐ wénhuà de nónghòu xìngqù.', 'Các hoạt động ngoại khóa học tập đa dạng cùng bài giảng khoa học thường thức đã khơi gợi hứng thú khám phá khoa học và văn hóa lịch sử của các em nhỏ.'), ('博物馆已成为一座没有围墙的开放式大学，在潜移默化中滋养着整个社会的文明素养。', 'Bówùguǎn yǐ chéngwéi yí zuò méiyǒu wéiqiáng de kāifàngshì dàxué, zài qiányí-mòhuà zhōng zīyǎng zhe zhěnggè shèhuì de wénmíng sùyǎng.', 'Bảo tàng đã trở thành trường đại học mở không tường rào, âm thầm bồi đắp tố chất văn minh cho toàn xã hội qua từng ngày.')], [('Chuyển biến lớn nhất của bảo tàng hiện đại là gì?', ['Đóng cửa không cho công chúng vào', 'Coi trọng giáo dục xã hội và trải nghiệm tương tác cho khách tham quan', 'Bán hết hiện vật cổ'], 1, 'Trong bài có câu: 越来越重视自身的社会公共教育与互动体验功能.'), ('Công nghệ số và VR đem lại trải nghiệm gì cho người tham quan?', ['Tự tay tương tác và nhập vai cảm nhận hiện trường lịch sử sống động', 'Cảm giác nhàm chán', 'Làm hỏng hiện vật'], 0, 'Trong câu có viết: 亲手操作并沉浸式感知历史事件的发生现场.'), ('Bảo tàng được ví như hình ảnh gì trong xã hội hiện đại?', ['Kho chứa đồ phế liệu', 'Trường đại học mở không tường rào bồi đắp văn minh xã hội', 'Khu chợ buôn bán'], 1, 'Trong câu cuối có viết: 已成为一座没有围墙的开放式大学，在潜移默化中滋养着整个社会的文明素养.')]),
    (26, '跨文化商务礼仪的智慧', 'Sự tinh tế trong nghi thức thương mại đa văn hóa', 'business_etiquette', 'Thương mại quốc tế', '🌐', 5, 'Tôn trọng sự khác biệt văn hóa và ứng xử chuẩn mực trong kinh doanh quốc tế là chìa khóa mở ra cánh cửa hợp tác thành công.', [('在全球化深入发展的商务交往中，掌握得体的跨文化商务礼仪是赢得外商信任的前提条件。', 'Zài quánqiúhuà shēnrù fāzhǎn de shāngwù jiāowǎng zhōng, zhǎngwò détǐ de kuàwénhuà shāngwù lǐyí shì yíngdé wàishāng xìnrèn de qiántí tiáojiàn.', 'Trong giao thương thương mại thời toàn cầu hóa, nắm vững nghi thức kinh doanh đa văn hóa chuẩn mực là điều kiện tiên quyết để chiếm được lòng tin đối tác.'), ('不同国家和地区在肢体语言、名片交换方式以及会议时间观念上存在着明显的文化差异。', 'Bùtóng guójiā hé dìqū zài zhītǐ yǔyán, míngpiàn jiāohuàn fāngshì yǐjí huìyì shíjiān guānniàn shàng cúnzài zhe míngxiǎn de wénhuà chāyì.', 'Các quốc gia và khu vực khác nhau có sự khác biệt văn hóa rõ rệt về ngôn ngữ cơ thể, cách trao đổi danh thiếp cũng như quan niệm về thời gian hội nghị.'), ('例如在某些国家，双手递接名片并认真阅读是表示对谈判伙伴的崇高敬意。', 'Lìrú zài mǒuxiē guójiā, shuāngshǒu dì jiē míngpiàn bìng rènzhēn yuèdú shì biǎoshì duì tánpàn huǒbàn de chónggāo jìngyì.', 'Chẳng hạn tại một số quốc gia, đưa và nhận danh thiếp bằng hai tay rồi đọc kỹ là thể hiện sự kính trọng cao độ với đối tác đàm phán.'), ('在商务宴请中，细心尊重对方的宗教饮食禁忌，往往能在不经意间拉近彼此的心理距离。', 'Zài shāngwù yànqǐng zhōng, xìxīn zūnzhòng duìfāng de zōngjiào yǐnshí jìnjì, wǎngwǎng néng zài bùjīngyì jiān lājìn bǐcǐ de xīnlǐ jùlí.', 'Trong tiệc chiêu đãi thương mại, chú ý tôn trọng kiêng kỵ ăn uống tôn giáo của đối tác thường vô tình rút ngắn khoảng cách tâm lý.'), ('敏锐的文化洞察力与谦逊包容的沟通态度，能够化解潜在摩擦，为互利共赢奠定坚实基础。', 'Mǐnruì de wénhuà dòngchálì yǔ qiānxùn bāoróng de gōutōng tàidù, nénggòu huàjiě qiǎnzài mócā, wèi hùlì-gòngyíng diàndì jiānshí jīchǔ.', 'Sự nhạy bén sâu sắc về văn hóa và thái độ khiêm nhường bao dung có thể hóa giải ma sát tiềm ẩn, đặt nền móng vững chắc cho sự hợp tác cùng thắng.')], [('Điều kiện tiên quyết để chiếm được lòng tin của đối tác quốc tế là gì?', ['Nắm vững nghi thức kinh doanh đa văn hóa phù hợp', 'Ép đối tác làm theo ý mình', 'Không cần quan tâm văn hóa đối phương'], 0, 'Trong bài có câu: 掌握得体的跨文化商务礼仪是赢得外商信任的前提条件.'), ('Hành vi nào tại một số nước thể hiện sự tôn trọng khi trao danh thiếp?', ['Nhét danh thiếp vào túi ngay', 'Dùng hai tay đưa nhận và chăm chú đọc', 'Chỉ gửi danh thiếp qua mạng'], 1, 'Trong câu có viết: 双手递接名片并认真阅读是表示对谈判伙伴的崇高敬意.'), ('Hành động tinh tế nào trong bàn tiệc giúp kéo gần khoảng cách đối tác?', ['Gọi thật nhiều món đắt tiền', 'Tôn trọng các điều kiêng kỵ tôn giáo và ẩm thực của đối phương', 'Ép đối tác uống rượu'], 1, 'Trong câu có viết: 细心尊重对方的宗教饮食禁忌，往往能在不经意间拉近彼此的心理距离.')]),
    (27, '青年志愿服务与社会担当', 'Thanh niên tình nguyện và trách nhiệm phụng sự xã hội', 'volunteering', 'Xã hội & Cống hiến', '🌟', 5, 'Tham gia hoạt động tình nguyện giúp giới trẻ thấu hiểu xã hội, trưởng thành trong cống hiến và lan tỏa sự ấm áp.', [('现代青年积极参与社会志愿服务活动，正在成为展现当代年轻人社会责任感的一道亮丽风景。', 'Xiàndài qīngnián jījí cānyù shèhuì zhìyuàn fúwù huódòng, zhèngzài chéngwéi zhǎnxiàn dāngdài niánqīngrén shèhuì zérèngǎn de yí dào liànglì fēngjǐng.', 'Thanh niên thời nay tích cực tham gia các hoạt động tình nguyện xã hội đang trở thành nét đẹp rạng ngời thể hiện tinh thần trách nhiệm của thế hệ trẻ.'), ('从社区敬老助残、城市大型赛事服务到偏远山区的爱心辅导，到处都有青年志愿者忙碌的身影。', 'Cóng shèqū jìnglǎo zhùcán, chéngshì dàxíng sàishì fúwù dào piānyuǎn shānqū de àixīn fǔdǎo, dàochù dōu yǒu qīngnián zhìyuànzhě mánglù de shēnyǐng.', 'Từ chăm sóc người già khuyết tật ở khu phố, hỗ trợ sự kiện thể thao lớn cho tới phụ đạo yêu thương nơi vùng cao hẻo lánh, đâu đâu cũng thấy bóng dáng tình nguyện viên trẻ tuổi.'), ('通过真诚地关爱与帮助弱势群体，青年人不仅提升了人际交往能力，更体会到了生命的真正价值。', "Tōngguò zhēnchéng de guān'ài yǔ bāngzhù ruòshì qúntǐ, qīngniánrén bùjǐn tíshēng le rénjì jiāowǎng nénglì, gèng tǐhuì dào le shēngmìng de zhēnzhèng jiàzhí.", 'Bằng cách chân thành yêu thương và giúp đỡ nhóm yếu thế, người trẻ không chỉ nâng cao kỹ năng giao tiếp mà còn cảm nhận giá trị đích thực của sự sống.'), ('志愿服务不仅是在给予他人温暖，更是一场让年轻人走出自我狭小天地、实现精神升华的心灵之旅。', 'Zhìyuàn fúwù bùjǐn shì zài jǐyǔ tārén wēnnuǎn, gèng shì yì chǎng ràng niánqīngrén zǒu chū zìwǒ xiáxiǎo tiāndì, shíxiàn jīngshén shēnghuá de xīnlíng zhī lǚ.', 'Hoạt động tình nguyện không chỉ là trao đi hơi ấm cho người khác mà còn là chuyến hành trình giúp người trẻ bước ra khỏi vỏ bọc cá nhân chật hẹp để thăng hoa tinh thần.'), ('涓涓细流汇聚成爱的江海，青年的无私奉献正为社会的文明进步汇聚起源源不断的正能量。', 'Juānjuān xìliú huìjù chéng ài de jiānghǎi, qīngnián de wúsī fèngxiàn zhèng wèi shèhuì de wénmíng jìnbù huìjù qǐ yuányuán-bùduàn de zhèng néngliàng.', 'Những dòng suối nhỏ hòa thành biển lớn yêu thương, sự cống hiến quên mình của thanh niên đang hội tụ nguồn năng lượng tích cực không ngừng nghỉ cho tiến bộ xã hội.')], [('Hoạt động tình nguyện của thanh niên diễn ra ở những lĩnh vực nào?', ['Chỉ ở các trung tâm mua sắm', 'Giúp đỡ người già, hỗ trợ giải đấu lớn và dạy học cho trẻ em vùng cao', 'Chỉ làm trực tuyến trên máy tính'], 1, 'Trong bài có câu: 从社区敬老助残、城市大型赛事服务到偏远山区的爱心辅导.'), ('Thanh niên thu hoạch được gì quý giá nhất khi tham gia tình nguyện?', ['Kiếm được nhiều tiền thù lao', 'Nâng cao kỹ năng giao tiếp và cảm nhận sâu sắc giá trị cuộc sống', 'Được nổi tiếng ngay lập tức'], 1, 'Trong câu có viết: 不仅提升了人际交往能力，更体会到了生命的真正价值.'), ('Ý nghĩa tinh thần sâu xa của công việc tình nguyện đối với người trẻ là gì?', ['Bước ra khỏi thế giới cá nhân chật hẹp và thăng hoa tinh thần', 'Lãng phí thời gian học tập', 'Chỉ là phong trào nhất thời'], 0, 'Trong câu có viết: 让年轻人走出自我狭小天地、实现精神升华的心灵之旅.')]),
    (28, '睡眠科学与健康管理', 'Khoa học giấc ngủ và quản lý sức khỏe toàn diện', 'sleep_science', 'Khoa học & Sức khỏe', '🌙', 5, 'Hiểu đúng về nhịp sinh học và chu kỳ giấc ngủ giúp phục hồi năng lượng não bộ và duy trì hệ miễn dịch khỏe mạnh.', [('充足高质量的睡眠是人体维持正常新陈代谢与免疫系统稳定运转的生理基石。', 'Chōngzú gāozhìliàng de shuìmián shì réntǐ wéichí zhèngcháng xīndài-xièchè yǔ miǎnyì xìtǒng wěndìng yùnzhuǎn de shēnglǐ jīshí.', 'Giấc ngủ đủ giấc và chất lượng cao là nền tảng sinh lý duy trì quá trình trao đổi chất bình thường và sự vận hành ổn định của hệ miễn dịch.'), ('然而在现代社会中，繁重的工作压力与手机蓝光的刺激，导致越来越多的人长期饱受失眠困扰。', "Rán'ér zài xiàndài shèhuì zhōng, fánzhòng de gōngzuò yālì yǔ shǒujī lánguāng de cìjī, dǎozhì yuè lái yuè duō de rén chángqī bǎoshòu shīmián kùnrǎo.", 'Thế nhưng trong xã hội hiện đại, áp lực công việc nặng nề cùng sự kích thích của ánh sáng xanh điện thoại khiến ngày càng nhiều người khốn đốn vì mất ngủ triền miên.'), ('科学研究表明，深度睡眠阶段能够帮助大脑清理代谢产生的废物，并巩固白天的记忆信息。', 'Kēxué yánjiū biǎomíng, shēndù shuìmián jiēduàn nénggòu bāngzhù dànǎo qīnglǐ dàixiè chǎnshēng de fèiwù, bìng gǒnggù báitiān de jìyì xìnxī.', 'Nghiên cứu khoa học chỉ ra rằng giai đoạn ngủ sâu giúp não bộ đào thải chất thải chuyển hóa và củng cố các thông tin ghi nhớ ban ngày.'), ('睡前一小时尽量远离电子屏幕，保持卧室安静凉爽，是改善睡眠质量的有效做法。', 'Shuìqián yì xiǎoshí jǐnliàng yuǎnlí diànzǐ píngmù, bǎochí wòshì ānjìng liángshuǎng, shì gǎishàn shuìmián zhìliàng de yǒuxiào zuòfǎ.', 'Trước khi ngủ một tiếng cố gắng tránh xa màn hình điện tử, giữ phòng ngủ yên tĩnh thoáng mát là biện pháp hữu hiệu cải thiện chất lượng giấc ngủ.'), ('尊重人体的昼夜生理节律，养成规律作息的良好习惯，才能拥有充沛的精力和健康的体魄。', 'Zūnzhòng réntǐ de zhòuyè shēnglǐ jiélǜ, yǎngchéng guīlǜ zuòxī de liánghǎo xíguàn, cái néng yōngyǒu chōngpèi de jīnglì yǔ jiànkāng de tǐpò.', 'Tôn trọng nhịp sinh học ngày đêm của cơ thể, hình thành thói quen sinh hoạt điều độ mới có thể sở hữu nguồn năng lượng dồi dào và thể trạng khỏe mạnh.')], [('Tác nhân nào trong đời sống hiện đại thường gây ra chứng mất ngủ?', ['Không khí quá trong lành', 'Áp lực công việc đè nặng và kích thích từ ánh sáng xanh màn hình', 'Ăn nhiều rau củ'], 1, 'Trong bài có câu: 繁重的工作压力与手机蓝光的刺激，导致越来越多的人长期饱受失眠困扰.'), ('Giai đoạn ngủ sâu mang lại lợi ích quan trọng nào cho não bộ?', ['Giúp não dọn sạch chất cặn bã chuyển hóa và củng cố trí nhớ', 'Làm mất trí nhớ ban ngày', 'Khiến não ngừng hoạt động vĩnh viễn'], 0, 'Trong câu có viết: 帮助大脑清理代谢产生的废物，并巩固白天的记忆信息.'), ('Thói quen có lợi trước khi đi ngủ là gì?', ['Lướt điện thoại liên tục sát giờ ngủ', 'Tránh xa màn hình điện tử một tiếng trước khi ngủ và giữ phòng yên tĩnh', 'Bật đèn sáng chói'], 1, 'Trong câu có viết: 睡前一小时尽量远离电子屏幕，保持卧室安静凉爽.')]),
    (29, '现代农业的科技创新', 'Đột phá công nghệ trong nông nghiệp hiện đại', 'agritech', 'Nông nghiệp công nghệ cao', '🚜', 5, 'Máy bay không người lái, cảm biến nhà kính và trí tuệ nhân tạo đang biến nghề nông truyền thống thành ngành kinh tế công nghệ cao.', [('告别了过去靠天吃饭的传统农耕模式，科技创新正在深刻改变着现代农业的面貌。', 'Gàobié le guòqù kào tiān chī fàn de chuántǒng nónggēng móshì, kējì chuàngxīn zhèngzài shēnkè gǎibiàn zhe xiàndài nóngyè de miànmào.', 'Tạm biệt phương thức làm nông truyền thống phụ thuộc hoàn toàn vào thời tiết của quá khứ, đổi mới công nghệ đang làm thay đổi sâu sắc diện mạo nông nghiệp hiện đại.'), ('无人机在广袤的农田上空自主巡航，精准喷洒农药与肥料，作业效率是以往人工操作的数十倍。', 'Wúrénjī zài guǎngmào de nóngtián shàngkōng zìzhǔ xúnháng, jīngzhǔn pēnsǎ nóngyào yǔ féiliào, zuòyè xiàolǜ shì yǐwǎng réngōng cāozuò de shù shí bèi.', 'Máy bay không người lái tự hành bay lượn trên đồng ruộng bạt ngàn, phun thuốc trừ sâu và phân bón chuẩn xác, năng suất gấp hàng chục lần so với sức người thủ công trước kia.'), ('智能温室大棚内安装的各类环境传感器，能够全天候监测土壤湿度、光照强度与温度变化。', 'Zhìnéng wēnshì dàpéng nèi ānzhuāng de gèlèi huánjìng chuángǎnqì, nénggòu quántiānhòu jiāncè tǔrǎng shīdù, guāngzhào qiángdù yǔ wēndù biànhuà.', 'Các cảm biến môi trường lắp đặt trong nhà kính thông minh có thể giám sát độ ẩm đất, cường độ ánh sáng và nhiệt độ suốt 24/7.'), ('通过科学精准的水肥一体化管理，农作物产量大幅提升，同时节约了宝贵的水资源。', 'Tōngguò kēxué jīngzhǔn de shuǐ-féi yītǐhuà guǎnlǐ, nóngzuòwù chǎnliàng dàfú tíshēng, tóngshí jiéyuē le bǎoguì de shuǐ zīyuán.', 'Nhờ quản lý tích hợp nước và phân bón khoa học chuẩn xác, sản lượng cây trồng tăng vọt, đồng thời tiết kiệm nguồn tài nguyên nước quý báu.'), ('智慧农业的发展不仅保障了国家粮食安全，更为实现农业绿色高质量发展开辟了广阔前景。', 'Zhìhuì nóngyè de fāzhǎn bùjǐn bǎozhàng le guójiā liángshi ānquán, gèng wèi shíxiàn nóngyè lǜsè gāozhìliàng fāzhǎn kāipì le guǎngkuò qiánjǐng.', 'Sự phát triển của nông nghiệp thông minh không chỉ bảo đảm an ninh lương thực quốc gia mà còn mở ra tiền đồ rộng lớn cho phát triển nông nghiệp xanh chất lượng cao.')], [('Ưu thế nổi trội của máy bay không người lái trong đồng ruộng là gì?', ['Phun thuốc và phân bón chuẩn xác với hiệu suất gấp hàng chục lần nhân công', 'Thay thế hoàn toàn giống lúa', 'Chỉ dùng để chụp ảnh phong cảnh'], 0, 'Trong bài có câu: 精准喷洒农药与肥料，作业效率是以往人工操作的数十倍.'), ('Cảm biến trong nhà kính thông minh thực hiện nhiệm vụ gì?', ['Thu hoạch rau củ tự động', 'Giám sát 24/7 độ ẩm đất, ánh sáng và biến đổi nhiệt độ', 'Tưới nước ngập ruộng'], 1, 'Trong câu có viết: 全天候监测土壤湿度、光照强度与温度变化.'), ('Ý nghĩa chiến lược của nông nghiệp thông minh đối với đất nước là gì?', ['Chỉ để xuất khẩu thiết bị', 'Bảo đảm an ninh lương thực và phát triển nông nghiệp xanh bền vững', 'Làm giá gạo tăng cao'], 1, 'Trong câu cuối có viết: 不仅保障了国家粮食安全，更为实现农业绿色高质量发展开辟了广阔前景.')]),
    (30, '音乐疗愈与心灵放松', 'Liệu pháp âm nhạc và thư giãn tinh thần', 'music_therapy', 'Nghệ thuật & Trị liệu', '🎵', 5, 'Giai điệu du dương có khả năng xoa dịu tổn thương tâm lý, giải tỏa căng thẳng và mang lại trạng thái cân bằng nội tâm.', [('音乐是人类共通的心灵语言，自古以来就具有洗涤心灵、抚慰创伤的神奇力量。', 'Yīnyuè shì rénlèi gòngtōng de xīnlíng yǔyán, zìgǔ yǐlái jiù jùyǒu xǐdí xīnlíng, fǔwèi chuāngshāng de shénqí lìliàng.', 'Âm nhạc là ngôn ngữ tâm hồn chung của nhân loại, từ ngàn xưa đã có sức mạnh diệu kỳ gột rửa tâm hồn và xoa dịu những vết thương lòng.'), ('现代医学中的音乐疗法，正是通过特定旋律与节奏的刺激，帮助患者调节紊乱的情绪。', 'Xiàndài yīxué zhōng de yīnyuè liáofǎ, zhèng shì tōngguò tèdìng xuánlǜ yǔ jiézòu de cìjī, bāngzhù huànzhě tiáojié wènluàn de qíngxù.', 'Liệu pháp âm nhạc trong y học hiện đại chính là thông qua kích thích của các giai điệu và tiết tấu đặc thù để giúp bệnh nhân điều hòa cảm xúc rối loạn.'), ('轻柔舒缓的古典乐曲能够降低交感神经的兴奋度，使紧绷的肌肉得到彻底放松。', 'Qīngróu shūhuǎn de gǔdiǎn yuèqǔ nénggòu jiàngdī jiāogǎn-shénjīng de xīngfèndù, shǐ jǐnbēng de jīròu dédào chèdǐ fàngsōng.', 'Những khúc nhạc cổ điển êm dịu có thể làm dịu sự phấn khích của hệ thần kinh giao cảm, giúp các cơ bắp căng thẳng được thả lỏng hoàn toàn.'), ('在沉浸式的音乐体验中，人们往往能够宣泄深藏心底的压抑与悲伤，重新获得前行的勇气。', 'Zài chénjìnshì de yīnyuè tǐyàn zhōng, rénmen wǎngwǎng nénggòu xuānxiè shēncáng xīndǐ de yāyì yǔ bēishāng, chóngxīn huòdé qiánxíng de yǒngqì.', 'Trong trải nghiệm âm nhạc đắm chìm, mọi người thường có thể trút bỏ nỗi u uất và bi thương giấu kín đáy lòng, lấy lại dũng khí tiến về phía trước.'), ('让优美的旋律融入日常生活，如同给疲惫的心灵注入一缕甘甜的清泉，带来持久的安宁。', 'Ràng yōuměi de xuánlǜ róngrù rìcháng shēnghuó, rútóng gěi píbèi de xīnlíng zhùrù yì lǚ gāntián de qīngquán, dàilái chíjiǔ de ānníng.', 'Để những giai điệu tuyệt mỹ hòa vào đời sống thường nhật tựa như rót một dòng suối trong ngọt ngào vào tâm hồn mỏi mệt, đem lại sự bình an dài lâu.')], [('Cơ chế của liệu pháp âm nhạc trong y học hiện đại là gì?', ['Bắt bệnh nhân học thuộc lời bài hát', 'Dùng giai điệu và tiết tấu đặc thù để điều hòa cảm xúc rối loạn', 'Bật nhạc lớn hết cỡ'], 1, 'Trong bài có câu: 通过特定旋律与节奏的刺激，帮助患者调节紊乱的情绪.'), ('Tác dụng thể chất của các khúc nhạc cổ điển êm dịu là gì?', ['Làm cơ bắp căng thẳng hơn', 'Giảm sự hưng phấn của thần kinh giao cảm và giúp cơ bắp thư giãn', 'Gây chóng mặt'], 1, 'Trong câu có viết: 降低交感神经的兴奋度，使紧绷的肌肉得到彻底放松.'), ('Âm nhạc đẹp được ví như hình ảnh gì cho tâm hồn con người?', ['Cơn mưa bão lớn', 'Dòng suối ngọt lành mang lại sự bình an dài lâu', 'Bức tường thành ngăn cách'], 1, 'Trong câu cuối có viết: 如同给疲惫的心灵注入一缕甘甜的清泉，带来持久的安宁.')]),
    (31, '环保理念融入日常消费', 'Ý thức bảo vệ môi trường trong hành vi tiêu dùng', 'green_consumption', 'Môi trường & Tiêu dùng', '♻️', 5, 'Người tiêu dùng ngày càng ưu tiên các sản phẩm tái chế, giảm đồ nhựa dùng một lần để bảo vệ hành tinh xanh.', [('随着全社会生态意识的显著觉醒，绿色低碳理念正在深刻改变着人们的日常消费选择。', 'Suízhe quán shèhuì shēngtài yìshí de xiǎnzhù juéxǐng, lǜsè dītàn lǐniàn zhèngzài shēnkè gǎibiàn zhe rénmen de rìcháng xiāofèi xuǎnzé.', 'Cùng với sự thức tỉnh rõ rệt của ý thức sinh thái trong toàn xã hội, quan niệm sống xanh carbon thấp đang làm thay đổi sâu sắc các lựa chọn tiêu dùng thường nhật.'), ('去超市购物时自带可循环布袋、自觉减少一次性塑料餐具的使用，已逐渐成为一种新的生活时尚。', 'Qù chāoshì gòuwù shí zìdài kě xúnhuán bùdài, zìjué jiǎnshǎo yícìxìng sùliào cānjù de shǐyòng, yǐ zhújiàn chéngwéi yì zhǒng xīn de shēnghuó shíshàng.', 'Tự mang túi vải tái sử dụng khi đi siêu thị, tự giác giảm thiểu đồ nhựa dùng một lần đã dần trở thành một phong cách sống thời thượng mới.'), ('越来越多的年轻人开始倾向于选购带有环保认证标签的商品，哪怕价格稍贵也心甘情愿。', 'Yuè lái yuè duō de niánqīngrén kāishǐ qīngxiàng yú xuǎngòu dài yǒu huánbǎo rènzhèng biāoqiān de shāngpǐn, nǎpà jiàgé shāo guì yě xīngān-qíngyuàn.', 'Ngày càng nhiều người trẻ có xu hướng chọn mua các mặt hàng có nhãn chứng nhận thân thiện với môi trường, dẫu giá cả có nhỉnh hơn đôi chút họ vẫn vui lòng.'), ('企业为了迎合这种消费趋势，纷纷加大研发投入，推出采用环保降解材料制造的产品。', 'Qǐyè wèile yínghé zhè zhǒng xiāofèi qūshì, fēnfēn jiàdà yánfā tóurù, tuīchū cǎiyòng huánbǎo jiàngjiě cáiliào zhìzào de chǎnpǐn.', 'Nhằm đáp ứng xu hướng tiêu dùng này, các doanh nghiệp đua nhau tăng cường vốn nghiên cứu, cho ra mắt các sản phẩm làm từ vật liệu tự phân hủy sinh học.'), ('每一个微小的绿色消费选择汇聚起来，都能成为守护地球美丽家园的巨大推动力。', 'Měi yí gè wēixiǎo de lǜsè xiāofèi xuǎnzé huìjù qǐlái, dōu néng chéngwéi shǒuhù dìqiú měilì jiāyuán de jùdà tuīdònglì.', 'Mỗi lựa chọn tiêu dùng xanh nhỏ bé khi hội tụ lại đều có thể trở thành động lực to lớn bảo vệ mái nhà trái đất tươi đẹp.')], [('Hành vi nào thể hiện thói quen tiêu dùng xanh khi đi mua sắm?', ['Lấy thật nhiều túi nilon', 'Tự mang túi vải tái sử dụng và hạn chế đồ nhựa một lần', 'Chỉ mua đồ đóng gói nhiều lớp'], 1, 'Trong bài có câu: 自带可循环布袋、自觉减少一次性塑料餐具的使用.'), ('Xu hướng chọn mua hàng của người tiêu dùng trẻ hiện nay là gì?', ['Ưu tiên hàng có chứng nhận bảo vệ môi trường', 'Chỉ mua hàng rẻ nhất không rõ nguồn gốc', 'Mua đồ khó phân hủy'], 0, 'Trong câu có viết: 倾向于选购带有环保认证标签的商品.'), ('Các doanh nghiệp phản ứng thế nào trước xu hướng tiêu dùng xanh?', ['Ngừng sản xuất', 'Tăng đầu tư nghiên cứu và cho ra mắt sản phẩm từ vật liệu tự phân hủy', 'Tăng giá sản phẩm vô cớ'], 1, 'Trong câu có viết: 加大研发投入，推出采用环保降解材料制造的产品.')]),
    (32, '远程办公与生活平衡', 'Làm việc từ xa và tìm kiếm sự cân bằng đời sống', 'remote_work', 'Xu hướng công việc', '💻', 5, 'Linh hoạt về địa điểm và thời gian làm việc mang lại nhiều cơ hội nhưng cũng đòi hỏi kỹ năng tự quản lý nghiêm túc.', [('互联网协作软件与云计算的飞速普及，使得远程办公逐渐从应急手段转变为一种常态化的工作模式。', 'Hùliánwǎng xiézuò ruǎnjiàn yǔ yúnsuànsuàn de fēisù pǔjí, shǐde yuǎnchéng bàngōng zhújiàn cóng yìngjí shǒuduàn zhuǎnbiàn wéi yì zhǒng chángtàihuà de gōngzuò móshì.', 'Sự phổ cập của phần mềm cộng tác trực tuyến và điện toán đám mây khiến làm việc từ xa dần chuyển từ biện pháp tình thế thành phương thức làm việc bình thường.'), ('员工不再需要每天忍受早晚高峰漫长而拥挤的通勤，能够更加自由灵活地规划个人日程。', 'Yuángōng bú zài xūyào měitiān rěnshòu zǎowǎn gāofēng màncháng ér yōngjǐ de tōngqín, nénggòu gèngjiā zìyóu línghuó de guīhuà gèrén rìchéng.', 'Nhân viên không còn phải chịu đựng cảnh đi lại tắc đường dài dặc vào giờ cao điểm, có thể tự do linh hoạt hơn trong sắp xếp lịch trình cá nhân.'), ('然而，工作与居家生活的界限逐渐模糊，也容易导致一些人陷入无休止加班的精神疲惫中。', "Rán'ér, gōngzuò yǔ jūjiā shēnghuó de jièxiàn zhújiàn móhu, yě róngyì dǎozhì yìxiē rén xiànrù wúxiūzhǐ jiābān de jīngshén píbèi zhōng.", 'Tuy vậy, ranh giới giữa công việc và đời sống gia đình bị mờ nhạt cũng dễ khiến một số người rơi vào trạng thái kiệt sức vì làm thêm giờ triền miên.'), ('建立规律的作息时间表，设立独立的工作空间，并在下班后彻底关闭工作通讯，是保持平衡的良策。', 'Jiànlì guīlǜ de zuòxī shíjiānbiǎo, shèlì dúlì de gōngzuò kōngjiān, bìng zài xiàbān hòu chèdǐ guānbì gōngzuò tōngxùn, shì bǎochí pínghéng de liángcè.', 'Thiết lập thời gian biểu sinh hoạt quy củ, bố trí không gian làm việc riêng biệt và tắt hẳn ứng dụng công việc sau giờ làm là phương sách giữ cân bằng.'), ('唯有拥有高度的自律能力，才能在享受工作自由的同时，真正收获高质量的惬意生活。', 'Wéiyǒu yōngyǒu gāodù de zìlǜ nénglì, cái néng zài xiǎngshòu gōngzuò zìyóu de tóngshí, zhēnzhèng shōuhuò gāozhìliàng de qièyì shēnghuó.', 'Chỉ khi sở hữu tính tự giác cao độ, con người mới có thể vừa tận hưởng tự do trong công việc, vừa thực sự gặt hái cuộc sống thư thái chất lượng cao.')], [('Lợi ích rõ rệt của hình thức làm việc từ xa đối với nhân viên là gì?', ['Không cần làm việc nữa', 'Tránh được cảnh tắc đường giờ cao điểm và linh hoạt sắp xếp thời gian', 'Được trả lương gấp đôi'], 1, 'Trong bài có câu: 不再需要每天忍受早晚高峰漫长而拥挤的通勤，能够更加自由灵活地规划个人日程.'), ('Thách thức tiềm ẩn khi làm việc tại nhà là gì?', ['Ranh giới công việc và cuộc sống bị mờ nhạt, dễ dẫn đến kiệt sức vì làm việc liên tục', 'Không có mạng Internet', 'Không thể trò chuyện với ai'], 0, 'Trong câu có viết: 工作与居家生活的界限逐渐模糊，也容易导致一些人陷入无休止加班的精神疲惫中.'), ('Lời khuyên để duy trì sự cân bằng khi làm việc từ xa là gì?', ['Làm việc ngay trên giường ngủ', 'Lập thời gian biểu quy củ, có góc làm việc riêng và tắt thiết bị sau giờ làm', 'Làm việc suốt đêm'], 1, 'Trong câu có viết: 建立规律的作息时间表，设立独立的工作空间，并在下班后彻底关闭工作通讯.')]),
    (33, '古典建筑的榫卯结构', 'Trí tuệ mộng gỗ trong kiến trúc cổ điển', 'architecture', 'Kiến trúc cổ đại', '🪵', 5, 'Kỹ thuật kết nối gỗ không cần đinh kim loại thể hiện tài hoa đỉnh cao và tư duy hòa hợp với thiên nhiên của thợ mộc xưa.', [('中国古典木结构建筑以其精巧绝伦的榫卯工艺，在世界建筑史上留下了浓墨重彩的一笔。', 'Zhōngguó gǔdiǎn mù jiégòu jiànzhù yǐ qí jīngqiǎo-juélún de sǔnmǎo gōngyì, zài shìjiè jiànzhù shǐ shàng liúxià le nóngmò-zhòngcǎi de yì bǐ.', 'Kiến trúc kết cấu gỗ cổ điển Trung Hoa với kỹ thuật ghép mộng xước xảo diệu vô song đã để lại một nét son rực rỡ trong lịch sử kiến trúc thế giới.'), ('古代工匠不用一颗铁钉，仅凭凹凸相契的木构件相互咬合，就能搭建起巍峨坚固的殿堂与高楼。', 'Gǔdài gōngjiàng bú yòng yì kē tiědīng, jǐn píng āo-tū xiāngqì de mù gòujiàn xiānghù yǎohé, jiù néng dājiàn qǐ wéié jiāngù de diàntáng yǔ gāolóu.', 'Thợ thủ công xưa không cần dùng một chiếc đinh sắt, chỉ dựa vào các thanh gỗ lồi lõm ăn khớp chặt chẽ vào nhau là có thể dựng nên những điện đường nguy nga vững chãi.'), ('这种柔性连接结构具有优异的抗震性能，在发生剧烈地震时能够通过轻微形变吸收能量而不坍塌。', 'Zhè zhǒng róuxìng liánjiē jiégòu jùyǒu yōuyì de kàngzhèn xìngnéng, zài fāshēng jùliè dìzhèn shí nénggòu tōngguò qīngwēi xíngbiàn xīshōu néngliàng ér bù tāntā.', 'Kết cấu liên kết mềm dẻo này sở hữu tính năng chống động đất vượt trội, khi xảy ra rung chấn dữ dội có thể biến dạng nhẹ để triệt tiêu năng lượng mà không sụp đổ.'), ('许多千年古刹历经无数次自然灾害与风雨洗礼，至今依然傲然挺立，令人叹为观止。', 'Xǔduō qiān nián gǔchà lìjīng wúshù cì zìrán zāihài yǔ fēngyǔ xǐlǐ, zhìjīn yīrán àorán tǐnglì, lìng rén tànwéi-guānzhǐ.', 'Nhiều ngôi chùa cổ ngàn năm trải qua muôn vàn thiên tai và gió mưa gội rửa đến nay vẫn hiên ngang đứng vững, khiến hậu thế phải trầm trồ thán phục.'), ('榫卯智慧不仅体现了精益求精的工匠精神，更展示了人与自然材料和谐共存的东方哲学。', 'Sǔnmǎo zhìhuì bùjǐn tǐxiàn le jīngyì-qiújīng de gōngjiàng jīngshén, gèng zhǎnshì le rén yǔ zìrán cáiliào héxié gòngcún de dōngfāng zhéxué.', 'Trí tuệ mộng gỗ không chỉ thể hiện tinh thần nghệ nhân luôn theo đuổi sự hoàn hảo mà còn minh chứng cho triết lý phương Đông con người hòa hợp cùng vật liệu tự nhiên.')], [('Đặc điểm đáng kinh ngạc nhất của kỹ thuật ghép mộng mộng (榫卯) là gì?', ['Dùng rất nhiều đinh sắt dày', 'Không dùng đinh, chỉ dựa vào các khớp gỗ lồi lõm ăn khớp chặt chẽ', 'Dùng keo dán hiện đại'], 1, 'Trong bài có câu: 古代工匠不用一颗铁钉，仅凭凹凸相契的木构件相互咬合.'), ('Ưu điểm nổi bật của kết cấu mộng gỗ khi xảy ra động đất là gì?', ['Cứng đơ và dễ gãy', 'Có tính liên kết dẻo dai giúp hấp thụ năng lượng rung chấn mà không sụp đổ', 'Rơi ra từng mảnh nhỏ'], 1, 'Trong câu có viết: 优异的抗震性能，在发生剧烈地震时能够通过轻微形变吸收能量而不坍塌.'), ('Trí tuệ mộng gỗ phản ánh triết lý gì của phương Đông?', ['Con người chinh phục và phá hủy thiên nhiên', 'Con người hòa hợp cộng sinh cùng vật liệu tự nhiên và tinh thần nghệ nhân tinh xảo', 'Tiết kiệm chi phí tối đa'], 1, 'Trong câu cuối có viết: 不仅体现了工匠精神，更展示了人与自然材料和谐共存的东方哲学.')]),
    (34, '终身友谊的滋养与维系', 'Nuôi dưỡng và gìn giữ tình bạn tri kỷ suốt đời', 'friendship', 'Tình cảm & Đời sống', '☕', 5, 'Tình bạn chân thành tựa như dòng suối trong mát, cần sự thấu hiểu, chân thành và nâng niu qua năm tháng.', [('在人生的漫长旅途中，能够拥有几位志同道合、携手同行的挚友是极其珍贵的幸福。', 'Zài rénshēng de màncháng lǚtú zhōng, nénggòu yōngyǒu jǐ wèi zhìtóng-dàohé, xiéshǒu tóngxíng de zhìyǒu shì jíqí zhēnguì de xìngfú.', 'Trong hành trình dài của đời người, có được vài người tri kỷ cùng chí hướng kề vai sát cánh là niềm hạnh phúc vô cùng quý giá.'), ('随着年龄的增长与生活轨迹的改变，忙碌与距离常常会不知不觉疏远彼此的联络。', 'Suízhe niánlíng de zēngzhǎng yǔ shēnghuó guǐjì de gǎibiàn, mánglù yǔ jùlí chángcháng huì bùzhī-bùjué shūyuǎn bǐcǐ de liánluò.', 'Cùng với sự gia tăng của tuổi tác và thay đổi của quỹ đạo cuộc sống, bận rộn và khoảng cách địa lý thường vô tình làm thưa thớt những liên lạc.'), ('然而真正的友谊从来不在于天天朝夕相处，而在于彼此灵魂深处的默契与信任。', "Rán'ér zhēnzhèng de yǒuyì cónglái bú zàiyú tiāntiān zhāoxī-xiāngchǔ, ér zàiyú bǐcǐ línghún shēnchù de mòqì yǔ xìnrèn.", 'Thế nhưng tình bạn chân chính xưa nay không nằm ở việc ngày ngày phải quấn quýt bên nhau, mà nằm ở sự thấu hiểu ngầm và tin cậy tận đáy lòng.'), ('在对方经历困境与失意时，一句温暖的问候和默默的支持，胜过千言万语的花言巧语。', 'Zài duìfāng jīnglì kùnjìng yǔ shīyì shí, yí jù wēnnuǎn de wènhòu hé mòmò de zhīchí, shèng guò qiānyán-wànyǔ de huāyán-qiǎoyǔ.', 'Khi đối phương trải qua nghịch cảnh và thất ý, một lời hỏi thăm ấm áp và sự âm thầm ủng hộ còn quý hơn vạn lời mật ngọt chót lưỡi đầu môi.'), ('用心去经营与呵护友情，岁月沉淀下来的情谊便如同陈年美酒，历久弥香。', 'Yòngxīn qù jīngyíng yǔ hēhù yǒuqíng, suìyuè chéndiàn xiàlái de qíngyì biàn rútóng chénnián měijiǔ, lìjiǔ-míxiāng.', 'Tận tâm vun đắp và nâng niu tình bạn, tình nghĩa đọng lại qua năm tháng sẽ tựa như rượu ủ lâu năm, càng để lâu càng nồng nàn say đắm.')], [('Tình bạn chân chính thực sự dựa trên nền tảng nào?', ['Phải gặp nhau ăn uống mỗi ngày', 'Sự thấu hiểu ngầm và niềm tin cậy sâu sắc trong tâm hồn', 'Dựa trên lợi ích tiền bạc'], 1, 'Trong bài có câu: 而在于彼此灵魂深处的默契与信任.'), ('Hành động quý giá nhất khi bạn bè gặp hoạn nạn là gì?', ['Bỏ rơi không quan tâm', 'Một lời hỏi thăm ấm áp và sự ủng hộ âm thầm chân thành', 'Chỉ nói lời đãi bôi sáo rỗng'], 1, 'Trong câu có viết: 一句温暖的问候和默默的支持，胜过千言万语的花言巧语.'), ('Tình bạn lâu năm được ví với hình ảnh gì trong bài viết?', ['Cơn gió thoảng qua', 'Bình rượu ủ lâu năm càng để càng thơm nồng', 'Bông hoa sớm nở tối tàn'], 1, 'Trong câu cuối có viết: 便如同陈年美酒，历久弥香.')]),
    (35, '体育精神与毅力磨砺', 'Tinh thần thể thao và sự tôi luyện ý chí bền bỉ', 'sportsmanship', 'Thể thao & Ý chí', '🏃', 5, 'Ý nghĩa đích thực của thể thao không chỉ là tấm huy chương mà là tinh thần không bỏ cuộc trước giới hạn bản thân.', [('体育运动的魅力远远超越了胜负本身，它是一场对人类体能与意志极限的勇敢挑战。', 'Tǐyù yùndòng de mèilì yuǎnyuǎn chāoyuè le shèngfù běnshēn, tā shì yì chǎng duì rénlèi tǐnéng yǔ yìzhì jíxiàn de yǒnggǎn tiǎozhàn.', 'Sức hấp dẫn của thể thao vượt xa khỏi ranh giới thắng bại thông thường, đó là cuộc thử thách dũng cảm với giới hạn thể lực và ý chí của con người.'), ('赛场上的运动员经过数年如一日艰辛枯燥的训练，汗水浸透了每一个清晨与黄昏。', 'Sàichǎng shàng de yùndòngyuán jīngguò shù nián rú yí rì jiānxīn kūzào de xùnliàn, hànshuǐ jìntòu le měi yí gè qīngchén yǔ huánghūn.', 'Các vận động viên trên sân đấu trải qua nhiều năm tháng khổ luyện đơn điệu bền bỉ, mồ hôi thấm đẫm từng sớm mai cho đến hoàng hôn.'), ('面对伤病的折磨与落后的压力，唯有永不放弃的坚韧品格才能帮助他们逆风翻盘。', 'Miànduì shāngbìng de zhémó yǔ luòhòu de yālì, wéiyǒu yǒng bú fàngqì de jiānrèn pǐngé cái néng bāngzhù tāmen nìfēng fānpán.', 'Đối diện với sự dày vò của chấn thương và áp lực bị dẫn điểm, chỉ có phẩm chất kiên cường không bao giờ bỏ cuộc mới giúp họ lội ngược dòng.'), ('尊重对手、恪守规则、在挫折面前昂首挺胸，是奥林匹克精神最动人的核心价值。', 'Zūnzhòng duìshǒu, kèshǒu guīzé, zài cuòzhé miànqián ángshǒu-tǐngxiōng, shì Àolínpǐkè jīngshén zuì dòngrén de héxīn jiàzhí.', 'Tôn trọng đối thủ, tuân thủ nghiêm ngặt luật lệ và ngẩng cao đầu trước thất bại là giá trị cốt lõi cảm động nhất của tinh thần Olympic.'), ('把运动场上的拼搏毅力带入现实生活，我们便能坦然面对任何坎坷，成为自己人生的冠军。', 'Bǎ yùndòngchǎng shàng de pīnbó yìlì dài rù xiànshí shēnghuó, wǒmen biàn néng tǎnrán miànduì rènhé kǎnkě, chéngwéi zìjǐ rénshēng de guànjūn.', 'Đem ý chí chiến đấu ngoan cường trên sân đấu vào cuộc sống thực tế, ta có thể bình thản đối mặt mọi gập ghềnh để trở thành quán quân của chính đời mình.')], [('Giá trị sâu xa của phong trào thể thao vượt lên trên điều gì?', ['Vượt lên trên tiền thưởng', 'Vượt lên trên thắng bại đơn thuần để thử thách giới hạn ý chí và thể lực', 'Chỉ để biểu diễn cho vui'], 1, 'Trong bài có câu: 远远超越了胜负本身，它是一场对人类体能与意志极限的勇敢挑战.'), ('Giá trị cốt lõi cảm động của tinh thần Olympic bao gồm điều gì?', ['Dùng mọi cách để thắng', 'Tôn trọng đối thủ, tuân thủ luật lệ và ngẩng cao đầu trước thất bại', 'Chê bai người thua cuộc'], 1, 'Trong câu có viết: 尊重对手、恪守规则、在挫折面前昂首挺胸.'), ('Bài học quý báu nhất mà thể thao mang lại cho cuộc đời là gì?', ['Phải trở thành vận động viên chuyên nghiệp', 'Đem ý chí kiên cường vào đời thực để vượt qua mọi chông gai', 'Tránh né mọi khó khăn'], 1, 'Trong câu cuối có viết: 把拼搏毅力带入现实生活，我们便能坦然面对任何坎坷.')]),
    (36, '数字化时代的纸质书温度', 'Độ ấm của sách giấy giữa thời đại số hóa', 'reading_culture', 'Văn hóa đọc', '📖', 5, 'Mùi mực in thơm dịu và cảm giác lật giở từng trang giấy mang lại trải nghiệm đọc sâu lắng khó thay thế.', [('电子阅读器和手机屏幕让海量书籍变得触手可及，极大地便利了现代人的碎片化阅读。', 'Diànzǐ yuèdúqì hé shǒujī píngmù ràng hǎiliàng shūjí biàn de chùshǒu-kějí, jídà de biànlì le xiàndàirén de suìpiànhuà yuèdú.', 'Máy đọc sách điện tử và màn hình điện thoại giúp hàng vạn cuốn sách nằm trong tầm tay, tạo thuận lợi lớn cho việc đọc phân mảnh của người hiện đại.'), ('然而在许多爱书人心中，捧在手中的纸质书依然散发着无可替代的温润气息。', "Rán'ér zài xǔduō àishūrén xīnzhōng, pěng zài shǒuzhōng de zhǐzhì shū yīrán sànfā zhe wúkě-tìdài de wēnrùn qìxī.", 'Thế nhưng trong lòng những người yêu sách, cuốn sách giấy cầm trên tay vẫn tỏa ra hơi thở ấm áp dịu dàng không gì thay thế được.'), ('指尖滑过纸张的微妙触感，淡淡的油墨清香，伴随着翻书时清脆的声响，共同构成了美妙的感官享受。', 'Zhǐjiān huá guò zhǐzhāng de wēimiào chùgǎn, dàndàn de yóumò qīngxiāng, bànsuí zhe fānshū shí qīngcuì de shēngxiǎng, gòngtóng gòuchéng le měimiào de gǎnguān xiǎngshòu.', 'Cảm giác tinh tế khi đầu ngón tay lướt trên trang giấy, mùi mực in thoang thoảng cùng tiếng lật sách giòn tan hòa quyện tạo thành trải nghiệm giác quan tuyệt diệu.'), ('不插电的阅读环境阻隔了社交媒体弹窗的打扰，让读者更容易沉下心来进入专注的深度思考。', 'Bù chādiàn de yuèdú huánjìng zǔgé le shèjiāo méitǐ tánchuāng de dǎrǎo, ràng dúzhě gèng róngyì chén xià xīn lái jìnrù zhuānzhù de shēndù sīkǎo.', 'Môi trường đọc không cắm điện ngăn chặn sự quấy nhiễu của thông báo mạng xã hội, giúp người đọc dễ dàng tĩnh tâm bước vào suy ngẫm sâu sắc.'), ('阳光洒落在书页上的静谧午后，纸质书所承载的不仅是知识，更是一段慢下来的诗意时光。', 'Yángguāng sǎluò zài shūyè shàng de jìngmì wǔhòu, zhǐzhì shū suǒ chéngzài de bùjǐn shì zhīshi, gèng shì yí duàn màn xiàlái de shīyì shíguāng.', 'Dưới ánh nắng ban trưa rải nhẹ trên trang sách yên ả, sách giấy chuyên chở không chỉ là tri thức mà còn là quãng thời gian thi vị sống chậm.')], [('Điểm vượt trội của sách điện tử là gì?', ['Lượng sách phong phú tiện lợi trong tầm tay', 'Đắt hơn sách giấy', 'Nặng hơn sách giấy'], 0, 'Trong bài có câu: 让海量书籍变得触手可及，极大地便利了现代人的碎片化阅读.'), ('Trải nghiệm giác quan độc đáo mà sách giấy mang lại là gì?', ['Ánh sáng chói lóa', 'Cảm giác chạm ngón tay, mùi mực in và tiếng lật trang sách', 'Cần sạc pin liên tục'], 1, 'Trong câu có viết: 指尖滑过纸张的微妙触感，淡淡的油墨清香，伴随着翻书时清脆的声响.'), ('Vì sao môi trường đọc sách giấy giúp con người tư duy sâu hơn?', ['Vì không bị tin nhắn và thông báo mạng làm gián đoạn', 'Vì có nhiều hình ảnh hoạt hình', 'Vì sách giấy có nhạc phát ra'], 0, 'Trong câu có viết: 阻隔了社交媒体弹窗的打扰，让读者更容易沉下心来进入深度思考.')]),
    (37, '深度旅行的人文体验', 'Trải nghiệm nhân văn từ những chuyến du lịch chiều sâu', 'deep_travel', 'Du lịch & Văn hóa', '🧳', 5, 'Rời xa các điểm check-in vội vã, hòa mình vào đời sống cư dân bản địa để cảm nhận vẻ đẹp đích thực của miền đất mới.', [('许多传统的旅游模式往往停留在走马观花式的景点拍照打卡，难以留下深刻的情感记忆。', 'Xǔduō chuántǒng de lǚyóu móshì wǎngwǎng tíngliú zài zǒumǎ-guānhuā shì de jǐngdiǎn pāizhào dǎkǎ, nányǐ liúxià shēnkè de qínggǎn jìyì.', 'Nhiều mô hình du lịch truyền thống thường chỉ dừng lại ở cảnh cưỡi ngựa xem hoa chụp ảnh check-in tại các danh lam thắng cảnh, khó đọng lại ký ức sâu sắc.'), ('如今越来越多的人开始钟情于慢节奏的深度旅行，渴望走进目的地的街巷深处探寻风土人情。', 'Rújīn yuè lái yuè duō de rén kāishǐ zhōngqíng yú màn jiézòu de shēndù lǚxíng, kěwàng zǒujìn mùdìdì de jiēxiàng shēnchù tànxún fēngtǔ-rénqíng.', 'Ngày nay ngày càng nhiều người say mê các chuyến du lịch chậm và sâu, khao khát bước vào từng ngõ ngách sâu thẳm của điểm đến để tìm hiểu phong tục tập quán.'), ('在古老的小茶馆里与当地老人促膝长谈，或在清晨的热闹市集上挑选刚出炉的特色糕点，乐趣无穷。', 'Zài gǔlǎo de xiǎo cháguǎn lǐ yǔ dāngdì lǎorén cùxī chángtán, huò zài qīngchén de rènao shìjí shàng tiāoxuǎn gāng chūlú de tèsè gāodiǎn, lèqù-wúqióng.', 'Ngồi trong quán trà cổ đàm đạo cùng các cụ già địa phương, hay dạo bước chợ sáng náo nhiệt chọn bánh ngọt đặc sản mới ra lò mang lại niềm vui vô tận.'), ('这种浸润式的文化体验，让我们能够跳出自己固有的生活框架，学会以更加包容的视角打量世界。', 'Zhè zhǒng jìnrùnshì de wénhuà tǐyàn, ràng wǒmen nénggòu tiào chū zìjǐ gùyǒu de shēnghuó kuàngjià, xuéhuì yǐ gèngjiā bāoróng de shìjiǎo dǎliang shìjiè.', 'Trải nghiệm văn hóa thẩm thấu này giúp ta nhảy ra khỏi khuôn khổ đời sống cố hữu, học cách nhìn ngắm thế giới bằng lăng kính bao dung hơn.'), ('旅行的终极真谛不在于丈量了多少里程，而在于是否让心灵经历了一场开阔眼界的洗礼。', 'Lǚxíng de zhōngjí zhēndì bú zàiyú zhàngliáng le duōshao lǐchéng, ér zàiyú shìfǒu ràng xīnlíng jīnglì le yì chǎng kāikuò yǎnjiè de xǐlǐ.', 'Chân lý tối thượng của du lịch không phải đo đếm xem ta đã đi bao nhiêu dặm đường, mà là liệu tâm hồn đã trải qua một cuộc thanh lọc mở rộng tầm mắt hay chưa.')], [("Nhược điểm của kiểu du lịch 'cưỡi ngựa xem hoa' truyền thống là gì?", ['Chỉ chụp ảnh check-in vội vã, khó đọng lại ký ức cảm xúc sâu sắc', 'Tốn quá nhiều thời gian nghỉ ngơi', 'Phải nói chuyện quá nhiều'], 0, 'Trong bài có câu: 停留在走马观花式的景点拍照打卡，难以留下深刻的情感记忆.'), ('Du lịch chiều sâu (深度旅行) mang đến những hoạt động thú vị nào?', ['Ngồi trong khách sạn cả ngày', 'Trò chuyện cùng người bản xứ tại quán trà và khám phá chợ sáng', 'Chỉ đi trung tâm thương mại sang trọng'], 1, 'Trong câu có viết: 与当地老人促膝长谈，或在清晨的热闹市集上挑选特色糕点.'), ('Chân lý cốt lõi của du lịch theo tác giả là gì?', ['Đi được càng nhiều nước càng tốt', 'Giúp tâm hồn trải qua cuộc thanh lọc mở rộng tầm mắt', 'Mua thật nhiều quà lưu niệm'], 1, 'Trong câu cuối có viết: 不在于丈量了多少里程，而在于是否让心灵经历了一场开阔眼界的洗礼.')]),
    (38, '面对挫折的心理韧性', 'Nội lực kiên cường khi đương đầu với nghịch cảnh', 'resilience', 'Tâm lý học ứng dụng', '🌱', 5, 'Nghịch cảnh không phải ngõ cụt mà là lò luyện giúp con người rèn giũa bản lĩnh và trưởng thành chín chắn hơn.', [('人生并非总是一帆风顺的坦途，挫折与困境是每个人在成长过程中都必须经历的严峻考验。', 'Rénshēng bìng fēi zǒngshì yìfān-fēngshùn de tǎntú, cuòzhé yǔ kùnjìng shì měi gè rén zài chéngzhǎng guòchéng zhōng dōu bìxū jīnglì de yánjùn kǎoyàn.', 'Đường đời vốn dĩ không phải con đường bằng phẳng luôn thuận buồm xuôi gió, trắc trở và nghịch cảnh là bài kiểm tra cam go ai cũng phải trải qua.'), ('心理韧性强大的人并非从不感到悲伤或沮丧，而是他们拥有迅速从低谷中重新站起来的能力。', 'Xīnlǐ rènxìng qiángdà de rén bìng fēi cóng bù gǎndào bēishāng huò jǔsàng, ér shì tāmen yōngyǒu xùnsù cóng dīgǔ zhōng chóngxīn zhàn qǐlái de nénglì.', 'Người có nội lực tâm lý vững vàng không phải là người không bao giờ buồn đau hay nản chí, mà là người có năng lực nhanh chóng đứng dậy từ đáy vực.'), ('遇到失败时，避免陷入盲目自责的消极泥潭，理性分析问题背后的客观原因是破局的关键。', 'Yù dào shībài shí, bìmiǎn xiànrù mángmù zìzé de xiāojí nítán, lǐxìng fēnxī wèntí bèihòu de kèguān yuányīn shì pòjú de guānjiàn.', 'Khi thất bại, tránh sa lầy vào vũng bùn tự trách mù quáng mà cần phân tích lý tính nguyên nhân khách quan là chìa khóa tháo gỡ bế tắc.'), ('把每一次跌倒都视作汲取宝贵经验的契机，内心的抗压能力便会在磨砺中变得坚不可摧。', 'Bǎ měi yí cì diēdǎo dōu shì zuò jíqǔ bǎoguì jīngyàn de qìjī, nèixīn de kàngyā nénglì biàn huì zài mólì zhōng biàn de jiānbùkěcuī.', 'Xem mỗi lần vấp ngã là cơ hội tích lũy kinh nghiệm quý giá, sức chịu đựng áp lực nội tâm sẽ trở nên kiên cố không thể phá vỡ qua thử thách.'), ('穿过暴风雨的洗礼，我们终将蜕变成为一个更加成熟、自信且充满力量的自己。', 'Chuānguò bàofēngyǔ de xǐlǐ, wǒmen zhōng jiāng tuìbiàn chéngwéi yí gè gèngjiā chéngshú, zìxìn qiě chōngmǎn lìliàng de zìjǐ.', 'Đi qua sự gội rửa của cơn bão giông, ta chắc chắn sẽ lột xác thành một bản thân chín chắn hơn, tự tin hơn và ngập tràn sức mạnh.')], [('Đặc điểm của người có sức bền tâm lý mạnh mẽ là gì?', ['Không bao giờ biết buồn', 'Có khả năng nhanh chóng đứng dậy từ nghịch cảnh', 'Trốn tránh khó khăn'], 1, 'Trong bài có câu: 拥有迅速从低谷中重新站起来的能力.'), ('Hành động then chốt để tháo gỡ bế tắc khi gặp thất bại là gì?', ['Tự trách bản thân thậm tệ', 'Phân tích lý tính nguyên nhân khách quan thay vì sa lầy tiêu cực', 'Đổ lỗi cho người khác'], 1, 'Trong câu có viết: 避免陷入盲目自责的消极泥潭，理性分析问题背后的客观原因.'), ('Mỗi lần vấp ngã nên được nhìn nhận như thế nào?', ['Là dấu chấm hết cho sự nghiệp', 'Là cơ hội quý báu tích lũy kinh nghiệm rèn luyện nội lực', 'Là sự xấu hổ không thể xóa bỏ'], 1, 'Trong câu có viết: 把每一次跌倒都视作汲取宝贵经验的契机.')]),
    (39, '极地冰川与气候预警', 'Băng hà vùng cực và lời cảnh báo biến đổi khí hậu', 'climate_change', 'Khí hậu & Địa cầu', '🧊', 5, 'Hiện tượng băng tan nhanh chóng tại hai cực phản ánh sự cấp bách của cuộc khủng hoảng khí hậu toàn cầu.', [('南北极覆盖的厚重冰川不仅是地球上最壮丽的自然景观，更是调节全球气候系统的巨大冷源。', 'Nán-běijí fùgài de hòuzhòng bīngchuān bùjǐn shì dìqiú shàng zuì zhuànglì de zìrán jǐngguān, gèng shì tiáojié quánqiú qìhòu xìtǒng de jùdà lěngyuán.', 'Những tảng băng hà dày đặc bao phủ hai cực Nam Bắc không chỉ là cảnh quan thiên nhiên tráng lệ nhất mà còn là nguồn làm lạnh khổng lồ điều tiết khí hậu toàn cầu.'), ('近几十年来全球气温的持续攀升，导致极地冰川融化的速度远远超出了科学家此前的预测。', 'Jìn jǐshí nián lái quánqiú qìwēn de chíxù pānshēng, dǎozhì jídì bīngchuān rónghuà de sùdù yuǎnyuǎn chāochū le kēxuéjiā cǐqián de yùcè.', 'Nhiệt độ toàn cầu không ngừng tăng cao trong vài thập kỷ qua khiến tốc độ băng tan ở hai cực vượt xa dự đoán trước đó của các nhà khoa học.'), ('海平面的加速上升不仅直接威胁着低洼沿海城市的安全，还严重破坏了北极熊等极地生物的栖息环境。', 'Hǎipíngmiàn de jiāsù shàngshēng bùjǐn zhíjiē wēixié zhe dīwā yánhǎi chéngshì de ānquán, hái yánzhòng pòhuài le běijíxióng děng jídì shēngwù de qīxī huánjìng.', 'Mực nước biển dâng nhanh không những đe dọa trực tiếp an toàn của các thành phố ven biển trũng thấp mà còn tàn phá môi trường sống của gấu Bắc cực và sinh vật vùng cực.'), ('极地冰川的消融如同地球向人类发出的红色警报，提醒我们应对全球气候变暖已经刻不容缓。', 'Jídì bīngchuān de xiāoróng rútóng dìqiú xiàng rénlèi fāchū de hóngsè jǐngbào, tíxǐng wǒmen yìngduì quánqiú qìhòu biànnuǎn yǐjīng kèbùrónghuǎn.', 'Băng tan vùng cực tựa như hồi chuông báo động đỏ của Trái đất gửi tới loài người, nhắc nhở rằng ứng phó với ấm lên toàn cầu đã cấp bách không thể chậm trễ.'), ('减少碳足迹、保护脆弱的极地生态，需要全球每一个国家和每一个人共同付诸坚决行动。', 'Jiǎnshǎo tànzújì, bǎohù cuìruò de jídì shēngtài, xūyào quánqiú měi yí gè guójiā hé měi yí gè rén gòngtóng fùzhū jiānjué xíngdòng.', 'Cắt giảm lượng phát thải carbon, bảo vệ sinh thái vùng cực mong manh đòi hỏi từng quốc gia và mỗi cá nhân trên toàn cầu cùng chung tay hành động dứt khoát.')], [('Vai trò quan trọng của băng hà ở hai cực đối với trái đất là gì?', ['Là nguồn tài nguyên khai thác mỏ', 'Là nguồn làm mát khổng lồ điều tiết hệ thống khí hậu toàn cầu', 'Không có tác dụng rõ rệt'], 1, 'Trong bài có câu: 更是调节全球气候系统的巨大冷源.'), ('Hậu quả nghiêm trọng của việc mực nước biển dâng nhanh là gì?', ['Đe dọa các thành phố duyên hải trũng thấp và phá hủy môi trường sống sinh vật cực', 'Làm biển sâu cạn nước', 'Tăng thêm đất liền'], 0, 'Trong câu có viết: 直接威胁着低洼沿海城市的安全，还严重破坏了北极熊等极地生物的栖息环境.'), ('Hiện tượng băng tan ở vùng cực được ví như điều gì?', ['Một trò chơi thú vị', 'Hồi chuông cảnh báo đỏ Trái Đất gửi tới nhân loại', 'Hiện tượng bình thường không đáng lo'], 1, 'Trong câu có viết: 如同地球向人类发出的红色警报，提醒我们刻不容缓.')]),
    (40, '现代舞台艺术的跨界创新', 'Đổi mới liên ngành trong nghệ thuật sân khấu đương đại', 'performing_arts', 'Sân khấu & Nghệ thuật', '🎭', 5, 'Sự kết hợp giữa kịch nghệ truyền thống, công nghệ kỹ thuật số và vũ đạo hiện đại mang đến diện mạo mới cho sân khấu.', [('当古典戏剧与现代多媒体技术在舞台上邂逅碰撞，一场震撼人心的视听盛宴便悄然诞生。', 'Dāng gǔdiǎn xìjù yǔ xiàndài duōméitǐ jìshù zài wǔtái shàng xièhòu pèngzhuàng, yì chǎng zhènhàn-rénxīn de shì-tīng shèngyàn biàn qiǎorán dànshēng.', 'Khi hí kịch cổ điển và công nghệ đa phương tiện hiện đại gặp gỡ va chạm trên sân khấu, một bữa tiệc nghe nhìn chấn động lòng người đã lặng lẽ chào đời.'), ('传统舞台往往受限于固定的布景道具，而全息投影与三维声效则打破了这一物理空间界限。', 'Chuántǒng wǔtái wǎngwǎng shòuxiàn yú gùdìng de bùjǐng dàojù, ér quánxī tóuyǐng yǔ sānwéi shēngxiào zé dǎpò le zhè yì wùlǐ kōngjiān jièxiàn.', 'Sân khấu truyền thống thường bị giới hạn bởi phông cảnh và đạo cụ cố định, trong khi hình chiếu 3D holographic và âm thanh vòm đã phá vỡ ranh giới không gian vật lý này.'), ('年轻的编导们大胆将传统戏曲唱腔与现代交响乐、当代舞肢体语言有机融为一体。', 'Niánqīng de biāndǎo men dàdǎn jiāng chuántǒng xìqǔ chàngqiāng yǔ xiàndài jiāoxiǎngyuè, dāngdài wǔ zhītǐ yǔyán yǒujī róng wéi yītǐ.', 'Các đạo diễn biên kịch trẻ tuổi táo bạo dung hợp làn điệu tuồng cổ truyền thống cùng nhạc giao hưởng hiện đại và ngôn ngữ hình thể múa đương đại.'), ('这种新颖独特的表现手法，成功打破了年轻一代对传统舞台艺术枯燥晦涩的刻板印象。', 'Zhè zhǒng xīnyǐng dútè de biǎoxiàn shǒufǎ, chénggōng dǎpò le niánqīng yídài duì chuántǒng wǔtái yìshù kūzào huìsè de kèbǎn yìnxiàng.', 'Thủ pháp biểu hiện mới mẻ độc đáo này đã phá vỡ thành công định kiến khô khan khó hiểu của thế hệ trẻ về nghệ thuật sân khấu cổ điển.'), ('艺术在坚守精神内核的同时勇敢拥抱现代创新，才能在时代的洪流中焕发勃勃生机。', 'Yìshù zài jiānshǒu jīngshén nèihé de tóngshí yǒnggǎn yōngbào xiàndài chuàngxīn, cái néng zài shídài de hóngliú zhōng huànfā bóbó shēngjī.', 'Nghệ thuật một khi vừa giữ vững cốt lõi tinh thần vừa dũng cảm đón nhận đổi mới hiện đại mới có thể bừng sáng sức sống dồi dào giữa dòng chảy thời đại.')], [('Công nghệ nào giúp sân khấu hiện đại vượt qua giới hạn phông cảnh truyền thống?', ['Vẽ tranh tường cố định', 'Hình chiếu 3D holographic và hiệu ứng âm thanh vòm', 'Tắt hết đèn sân khấu'], 1, 'Trong bài có câu: 全息投影与三维声效则打破了这一物理空间界限.'), ('Các đạo diễn trẻ đã kết hợp những yếu tố nghệ thuật nào?', ['Chỉ dùng nhạc nước ngoài', 'Làn điệu hí kịch truyền thống, nhạc giao hưởng và múa đương đại', 'Không dùng âm nhạc'], 1, 'Trong câu có viết: 将传统戏曲唱腔与现代交响乐、当代舞肢体语言有机融为一体.'), ('Sự đổi mới sân khấu đem lại hiệu quả tích cực nào đối với khán giả trẻ?', ['Làm khán giả rời đi', 'Xóa tan định kiến khô khan khó hiểu của thế hệ trẻ về nghệ thuật cổ truyền', 'Tăng giá vé gấp nhiều lần'], 1, 'Trong câu có viết: 成功打破了年轻一代对传统舞台艺术枯燥晦涩的刻板印象.')]),
    (41, '亲子教育中的倾听与尊重', 'Lắng nghe và tôn trọng trong giáo dục con cái', 'parenting', 'Gia đình & Nuôi dạy', '👨\u200d👩\u200d👦', 5, 'Làm bạn cùng con, tôn trọng cá tính và bình đẳng lắng nghe là chìa khóa nuôi dưỡng những đứa trẻ tự tin và hạnh phúc.', [('家庭是孩子性格与品格形成的第一所学校，父母的言传身教在潜移默化中塑造着孩子的未来。', 'Jiātíng shì háizi xìnggé yǔ pǐngé xíngchéng de dì-yī suǒ xuéxiào, fùmǔ de yánchuán-shēnjiào zài qiányí-mòhuà zhōng sùzào zhe háizi de wèilái.', 'Gia đình là ngôi trường đầu tiên hình thành tính cách và phẩm chất của trẻ, lời dạy và tấm gương của cha mẹ âm thầm nhào nặn nên tương lai của con.'), ('很多家长习惯于单向地向孩子灌输要求，却往往忽略了俯下身来倾听孩子的内心渴望。', 'Hěn duō jiāzhǎng xíguàn yú dānxiàng de xiàng háizi guànshū yāoqiú, què wǎngwǎng hūlüè le fǔ xià shēn lái qīngtīng háizi de nèixīn kěwàng.', 'Nhiều phụ huynh quen với việc áp đặt yêu cầu một chiều lên con cái, mà thường quên cúi mình xuống lắng nghe khao khát nội tâm của con.'), ('给孩子平等的发言权，耐心接纳他们的小情绪与不同想法，能够极大地培养孩子的独立人格。', 'Gěi háizi píngděng de fāyánquán, nàixīn jiēnà tāmen de xiǎo qíngxù yǔ bùtóng xiǎngfǎ, nénggòu jídà de péiyǎng háizi de dúlì réngé.', 'Trao cho con quyền lên tiếng bình đẳng, kiên nhẫn đón nhận những cảm xúc nhỏ và suy nghĩ khác biệt của con có thể bồi đắp nhân cách độc lập.'), ('当孩子犯错时，包容与引导远比严厉的责罚更能让他们深刻认识到问题所在。', 'Dāng háizi fàncuò shí, bāoróng yǔ yǐndǎo yuǎn bǐ yánlì de zéfá gèng néng ràng tāmen shēnkè rènshi dào wèntí suǒzài.', 'Khi con phạm lỗi, bao dung và định hướng mang lại hiệu quả sâu sắc hơn nhiều so với đòn roi trách phạt nghiêm khắc.'), ('建立在相互尊重与无条件信任基础上的亲子关系，是孩子一生最温暖坚实的心灵避风港。', 'Jiànlì zài xiānghù zūnzhòng yǔ wútiáojiàn xìnrèn jīchǔ shàng de qīnzǐ guānxi, shì háizi yìshēng zuì wēnnuǎn jiānshí de xīnlíng bìfēnggǎng.', 'Mối quan hệ cha mẹ - con cái được xây dựng trên nền tảng tôn trọng và tin tưởng vô điều kiện là bến đỗ bình yên ấm áp nhất suốt cuộc đời đứa trẻ.')], [('Thiếu sót phổ biến của nhiều bậc phụ huynh trong giao tiếp với con cái là gì?', ['Cho con quá nhiều đồ chơi', 'Áp đặt một chiều và không chịu lắng nghe nguyện vọng của con', 'Nói chuyện quá nhiều'], 1, 'Trong bài có câu: 习惯于单向地向孩子灌输要求，却往往忽略了俯下身来倾听孩子的内心渴望.'), ('Cách xử sự đúng đắn khi con mắc sai lầm là gì?', ['Mắng mỏ thậm tệ trước mặt người khác', 'Bao dung và định hướng giúp con hiểu bản chất vấn đề', 'Bỏ mặc không dạy dỗ'], 1, 'Trong câu có viết: 包容与引导远比严厉的责罚更能让他们深刻认识到问题所在.'), ('Bến đỗ tâm hồn ấm áp nhất cho trẻ em được xây dựng từ điều gì?', ['Tiền bạc và trường học đắt tiền', 'Sự tôn trọng lẫn nhau và niềm tin tưởng vô điều kiện', 'Sự kiểm soát nghiêm ngặt 24/7'], 1, 'Trong câu cuối có viết: 建立在相互尊重与无条件信任基础上的亲子关系.')]),
    (42, '共享经济的发展与反思', 'Bước tiến và những bài học từ nền kinh tế chia sẻ', 'sharing_economy', 'Kinh tế xã hội', '🚲', 5, 'Tận dụng tài nguyên nhàn rỗi mang lại lợi ích lớn nhưng cũng cần sự quản lý chặt chẽ để đảm bảo trật tự công cộng.', [('共享经济以盘活闲置资源、提高社会资源配置效率为核心，迅速风靡全球各大城市。', 'Gòngxiǎng jīngjì yǐ pánhuó xiánzhì zīyuán, tígāo shèhuì zīyuán pèizhì xiàolǜ wéi héxīn, xùnsù fēngmǐ quánqiú gè dà chéngshì.', 'Kinh tế chia sẻ với cốt lõi là kích hoạt tài nguyên nhàn rỗi và nâng cao hiệu quả phân bổ tài nguyên xã hội đã nhanh chóng gây sốt tại các thành phố lớn toàn cầu.'), ('从共享单车、共享充电宝到共享办公空间，这些创新业态极大丰富了人们的日常生活选择。', 'Cóng gòngxiǎng dānchē, gòngxiǎng chōngdiànbǎo dào gòngxiǎng bàngōng kōngjiān, zhèxiē chuàngxīn yètài jídà fēngfù le rénmen de rìcháng shēnghuó xuǎnzé.', 'Từ xe đạp chia sẻ, pin sạc dự phòng chia sẻ đến không gian làm việc chung, các mô hình đổi mới này đã làm phong phú lựa chọn thường nhật.'), ('然而在资本疯狂扩张的阶段，盲目过量投放也曾导致严重的城市公共空间乱象与资源浪费。', "Rán'ér zài zīběn fēngkuáng kuòzhāng de jiēduàn, mángmù guòliàng tóufàng yě céng dǎozhì yánzhòng de chéngshì gōnggòng kōngjiān luànxiàng yǔ zīyuán làngfèi.", 'Thế nhưng trong giai đoạn bành trướng tư bản điên cuồng, việc rải thừa thãi mù quáng từng gây ra cảnh lộn xộn không gian công cộng đô thị và lãng phí tài nguyên.'), ('通过大数据精确调度、完善押金监管机制以及规范用户停放行为，行业正在步入理性规范期。', 'Tōngguò dà shùjù jīngquè diàodù, wánshàn yājīn jiānguǎn jīzhì yǐjí guīfàn yònghù tíngfàng xíngwéi, hángyè zhèngzài bùrù lǐxìng guīfàn qī.', 'Nhờ dữ liệu lớn điều phối chuẩn xác, hoàn thiện cơ chế quản lý tiền cọc và chuẩn hóa hành vi đỗ xe của người dùng, ngành đang bước vào giai đoạn quy củ lý tính.'), ('只有在创新活力与精细化管理之间取得良性平衡，共享经济才能真正实现可持续的社会价值。', 'Zhǐyǒu zài chuàngxīn huólì yǔ jīngxìhuà guǎnlǐ zhījiān qǔdé liángxìng pínghéng, gòngxiǎng jīngjì cái néng zhēnzhèng shíxiàn kěchíxù de shèhuì jiàzhí.', 'Chỉ khi đạt được sự cân bằng lành mạnh giữa sức sống đổi mới và quản lý tinh vi, kinh tế chia sẻ mới thực sự tạo ra giá trị xã hội bền vững.')], [('Mục tiêu cốt lõi của mô hình kinh tế chia sẻ là gì?', ['Bán hàng tồn kho', 'Kích hoạt tài nguyên nhàn rỗi và tối ưu hóa hiệu quả phân bổ tài nguyên xã hội', 'Tăng chi phí sử dụng dịch vụ'], 1, 'Trong bài có câu: 盘活闲置资源、提高社会资源配置效率为核心.'), ('Vấn đề tiêu cực từng nảy sinh do việc bành trướng quá mức là gì?', ['Giá cả quá rẻ', 'Lộn xộn không gian công cộng đô thị và lãng phí tài nguyên', 'Không ai sử dụng sản phẩm'], 1, 'Trong câu có viết: 盲目过量投放也曾导致严重的城市公共空间乱象与资源浪费.'), ('Điều kiện để kinh tế chia sẻ phát triển bền vững là gì?', ['Cân bằng giữa sức sống đổi mới sáng tạo và quản lý tinh tế quy củ', 'Thả nổi hoàn toàn cho thị trường', 'Cấm mọi dịch vụ chia sẻ'], 0, 'Trong câu cuối có viết: 在创新活力与精细化管理之间取得良性平衡.')]),
    (43, '乡村支教的青春奉献', 'Tuổi trẻ cống hiến cho giáo dục vùng cao', 'rural_education', 'Giáo dục & Tình nguyện', '🏫', 5, 'Những thầy cô giáo trẻ mang theo tri thức và tình thương thắp sáng ước mơ cho học trò nơi bản làng xa xôi.', [('每年夏天，成千上万名优秀的大学毕业生毅然收拾行囊，奔赴中西部偏远乡村开展支教志愿活动。', 'Měinián xiàtiān, chéngqiān-shàngwàn míng yōuxiù de dàxué bìyèshēng yìrán shōushi xíngnang, bēnfù zhōng-xībù piānyuǎn xiāngcūn kāizhǎn zhījiào zhìyuàn huódòng.', 'Mỗi mùa hè, hàng vạn cử nhân đại học ưu tú kiên quyết thu xếp hành lý, lên đường tới các làng quê hẻo lánh miền Trung và Tây để dạy học tình nguyện.'), ('虽然当地的生活条件十分简陋，甚至经常停水停电，但孩子们渴望求知的清澈双眼让一切付出都变得值得。', 'Suīrán dāngdì de shēnghuó tiáojiàn shífēn jiǎnlòu, shènzhì chángcháng tíngshuǐ-tíngdiàn, dàn háizimen kěwàng qiúzhī de qīngchè shuāngyǎn ràng yíqiè fùchū dōu biàn de zhídé.', 'Dẫu điều kiện sinh hoạt nơi đây vô cùng đơn sơ, thậm chí thường xuyên mất điện mất nước, nhưng đôi mắt trong veo khao khát học hỏi của lũ trẻ làm cho mọi hy sinh đều xứng đáng.'), ('年轻教师们不仅教授语文与数学，还带来了生动有趣的音乐、美术以及科学实验课程。', 'Niánqīng jiàoshī men bùjǐn jiāoshòu yǔwén yǔ shùxué, hái dàilái le shēngdòng yǒuqù de yīnyuè, měishù yǐjí kēxué shíyàn kèchéng.', 'Các thầy cô giáo trẻ không chỉ dạy văn học và toán học, mà còn mang tới những tiết học âm nhạc, mỹ thuật và thí nghiệm khoa học sinh động thú vị.'), ('他们用爱心在封闭的大山与广阔的外部世界之间架起了一座桥梁，点亮了山村孩子心中的梦想。', 'Tāmen yòng àixīn zài fēngbì de dàshān yǔ guǎngkuò de wàibù shìjiè zhījiān jià qǐ le yí zuò qiáoliáng, diǎnliàng le shāncūn háizi xīnzhōng de mèngxiǎng.', 'Bằng trái tim nhân ái, họ đã bắc nhịp cầu nối giữa núi cao cách trở và thế giới rộng lớn bên ngoài, thắp sáng ước mơ trong lòng trẻ em bản làng.'), ('这段充满奉献与感动的支教岁月，也成为了这群青年人生命中最自豪且难忘的精神洗礼。', 'Zhè duàn chōngmǎn fèngxiàn yǔ gǎndòng de zhījiào suìyuè, yě chéngwéi le zhè qún qīngniánrén shēngmìng zhōng zuì zìháo qiě nánwàng de jīngshén xǐlǐ.', 'Năm tháng dạy học tình nguyện tràn ngập cống hiến và xúc động ấy cũng trở thành cuộc thanh lọc tinh thần tự hào và khó quên nhất đời người trẻ.')], [('Động lực lớn nhất giúp các thầy cô giáo trẻ vượt qua khó khăn thiếu thốn ở bản làng là gì?', ['Tiền lương cao', 'Ánh mắt trong trẻo khao khát tri thức của học trò vùng cao', 'Khí hậu mát mẻ'], 1, 'Trong bài có câu: 孩子们渴望求知的清澈双眼让一切付出都变得值得.'), ('Ngoài văn hóa và toán học, các tình nguyện viên còn dạy những môn gì?', ['Âm nhạc, mỹ thuật và các thí nghiệm khoa học sinh động', 'Chỉ bắt học sinh lao động', 'Dạy chơi game trực tuyến'], 0, 'Trong câu có viết: 带来了生动有趣的音乐、美术以及科学实验课程.'), ('Ý nghĩa lớn nhất của việc đi dạy vùng cao đối với bản thân người trẻ là gì?', ['Lãng phí tuổi xuân', 'Là cuộc thanh lọc tinh thần đáng tự hào và khó quên nhất trong đời', 'Để đi du lịch miễn phí'], 1, 'Trong câu cuối có viết: 成为生命中最自豪且难忘的精神洗礼.')]),
    (44, '二十四节气与自然法则', 'Hai mươi bốn tiết khí và quy luật tuần hoàn của tự nhiên', 'solar_terms', 'Văn hóa & Thiên nhiên', '☀️', 5, 'Di sản tri thức ngàn năm đúc kết từ quan sát thiên văn, mùa màng và đạo sống thuận theo tự nhiên của tiền nhân.', [('二十四节气是中国古代先民顺应农时、观察天象与物候变化而创造出的伟大知识体系。', 'Èrshísì jiéqì shì Zhōngguó gǔdài xiānmín shùnyìng nóngshí, guānchá tiānxiàng yǔ wùhòu biànhuà ér chuàngzào chū de wěidà zhīshi tǐxì.', 'Hai mươi bốn tiết khí là hệ thống tri thức vĩ đại do tiền nhân Trung Hoa cổ đại sáng tạo nên nhờ thuận theo thời vụ nông nghiệp, quan sát thiên tượng và biến đổi thời tiết.'), ('从春分、清明到白露、大雪，节气的更迭生动反映了阳光雨露在一年之中的起承转合。', 'Cóng Chūnfēn, Qīngmíng dào Báilù, Dàxuě, jiéqì de gēngdié shēngdòng fǎnyìng le yángguāng yǔlù zài yì nián zhīzhōng de qǐchéng-zhuǎnhé.', 'Từ Xuân Phân, Thanh Minh đến Bạch Lộ, Đại Tuyết, sự luân chuyển của tiết khí phản ánh sống động dòng chảy tuần hoàn của nắng mưa trong một năm.'), ('农民依据节气的指针合理安排播种、耕耘、收获与冬藏，世代传承着遵循自然规律的生产智慧。', 'Nóngmín yījù jiéqì de zhǐzhēn hélǐ ānpái bōzhǒng, gēngyún, shōuhuò yǔ dōngcáng, shìdài chuánchéng zhe zūnxún zìrán guīlǜ de shēngchǎn zhìhuì.', 'Người nông dân dựa vào kim chỉ nam của tiết khí để sắp xếp gieo hạt, cày cấy, thu hoạch và cất giữ vụ đông, đời đời truyền thừa trí tuệ sản xuất thuận tự nhiên.'), ('节气不仅指导着农业耕作，还深深融入了民间的饮食习俗、节庆仪式与中医养生学说中。', 'Jiéqì bùjǐn zhǐdǎo zhe nóngyè gēngzuò, hái shēnshēn róngrù le mínjiān de yǐnshí xísú, jiéqìng yíshì yǔ zhōngyī yǎngshēng xuéshuō zhōng.', 'Tiết khí không chỉ chỉ đạo việc đồng áng mà còn hòa sâu vào tập tục ẩm thực dân gian, nghi lễ lễ hội và học thuyết dưỡng sinh đông y.'), ('在工业文明的今天，重温节气智慧依然提醒我们要对大自然的周而复始怀抱敬畏与感恩之心。', "Zài gōngyè wénmíng de jīntiān, chóngwēn jiéqì zhìhuì yīrán tíxǐng wǒmen yào duì dàzìrán de zhōu'ér-fùshǐ huáibào jìngwèi yǔ gǎn'ēn zhī xīn.", 'Trong thời văn minh công nghiệp hôm nay, ôn lại trí tuệ tiết khí vẫn nhắc nhở ta phải giữ lòng kính sợ và biết ơn vòng tuần hoàn của tự nhiên.')], [('Hai mươi bốn tiết khí được sáng tạo dựa trên cơ sở nào?', ['Dự đoán ngẫu nhiên', 'Thuận theo mùa màng, quan sát hiện tượng thiên văn và biến chuyển vạn vật', 'Sao chép từ phương Tây'], 1, 'Trong bài có câu: 顺应农时、观察天象与物候变化而创造出的伟大知识体系.'), ('Ngoài chỉ đạo nông nghiệp, tiết khí còn ảnh hưởng sâu rộng đến lĩnh vực nào?', ['Chỉ dùng cho phong thủy', 'Ẩm thực dân gian, lễ hội truyền thống và dưỡng sinh đông y', 'Không ảnh hưởng đời sống'], 1, 'Trong câu có viết: 深深融入了民间的饮食习俗、节庆仪式与中医养生学说中.'), ('Thông điệp cốt lõi của trí tuệ tiết khí đối với con người hiện đại là gì?', ['Khai thác cạn kiệt thiên nhiên', 'Kính sợ và biết ơn vòng tuần hoàn bất tận của tự nhiên', 'Không cần quan tâm mùa màng'], 1, 'Trong câu cuối có viết: 对大自然的周而复始怀抱敬畏与感恩之心.')]),
    (45, '战胜拖延的行动哲学', 'Triết lý hành động đẩy lùi thói quen trì hoãn', 'time_management', 'Quản lý bản thân', '⏱️', 5, 'Chia nhỏ mục tiêu lớn thành những bước hành động đơn giản giúp giải phóng nỗi sợ và khôi phục sự chủ động.', [('拖延症是许多现代人在工作与学习中常常遭遇的心理障碍，常常导致极大的焦虑与内疚。', "Tuōyánzhèng shì xǔduō xiàndàirén zài gōngzuò yǔ xuéxí zhōng chángcháng zāoyù de xīnlǐ zhàng'ài, chángcháng dǎozhì jídà de jiāolǜ yǔ nèijiù.", 'Chứng trì hoãn là chướng ngại tâm lý mà nhiều người hiện đại thường gặp trong học tập và công việc, hay dẫn tới nỗi lo âu và tự trách cùng cực.'), ('心理学研究发现，拖延的根源往往不是单纯的懒惰，而是对失败的恐惧以及追求完美的心理压力。', 'Xīnlǐxué yánjiū fāxiàn, tuōyán de gēnyuán wǎngwǎng bú shì dānchún de lǎnduò, ér shì duì shībài de kǒngjù yǐjí zhuīqiú wánměi de xīnlǐ yālì.', 'Nghiên cứu tâm lý học nhận thấy nguồn cơn của sự trì hoãn thường không phải là lười biếng đơn thuần, mà là nỗi sợ thất bại và áp lực tâm lý cầu toàn quá mức.'), ('克服拖延最有效的策略，是将看似庞大艰巨的任务拆解为若干个微小且易于执行的具体步骤。', 'Kèfú tuōyán zuì yǒuxiào de cèlüè, shì jiāng kànsì pángdà jiānjù de rènwù chāijiě wéi ruògān gè wēixiǎo qiě yìyú zhíxíng de jùtǐ bùzhòu.', 'Chiến lược hiệu quả nhất để khắc phục trì hoãn là phân rã nhiệm vụ to lớn tưởng như bất khả thi thành những bước nhỏ cụ thể dễ dàng thực hiện.'), ('告诉自己只需要专注投入最初的五分钟，一旦迈出了第一步，惯性往往会推着我们继续前行。', 'Gàosù zìjǐ zhǐ xūyào zhuānxīn tóurù zuìchū de wǔ fēnzhōng, yídàn màichū le dì-yī bù, guànxìng wǎngwǎng huì tuī zhe wǒmen jìxù qiánxíng.', 'Hãy tự nhủ với bản thân chỉ cần chuyên tâm vào 5 phút đầu tiên, một khi đã cất bước chân mở đầu, quán tính thường sẽ đẩy ta tiếp tục tiến lên.'), ('停止不切实际的完美主义幻想，果断付诸即刻行动，是重掌生活掌控权的关键秘诀。', 'Tíngzhǐ búqiè-shíjì de wánměizhǔyì huànxiǎng, guǒduàn fùzhū jíkè xíngdòng, shì zhòngzhǎng shēnghuó zhǎngkòngquán de guānjiàn mìjué.', 'Dừng lại ảo tưởng cầu toàn thiếu thực tế, kiên quyết bắt tay hành động ngay lập tức là bí quyết then chốt để giành lại quyền làm chủ cuộc đời.')], [('Căn nguyên thực sự của chứng trì hoãn theo nghiên cứu tâm lý học là gì?', ['Do tính lười biếng bẩm sinh', 'Do nỗi sợ thất bại và áp lực của chủ nghĩa hoàn hảo quá đà', 'Do cơ thể thiếu ngủ'], 1, 'Trong bài có câu: 根源往往不是单纯的懒惰，而是对失败的恐惧以及追求完美的心理压力.'), ("Quy tắc '5 phút đầu tiên' có tác dụng gì?", ['Làm việc 5 phút rồi nghỉ', 'Giúp vượt qua sức ỳ ban đầu để quán tính tiếp tục đẩy ta hoàn thành công việc', 'Gây mất tập trung'], 1, 'Trong câu có viết: 一旦迈出了第一步，惯性往往会推着我们继续前行.'), ('Bí quyết để giành lại quyền chủ động trong cuộc sống là gì?', ['Chờ đợi nguồn cảm hứng hoàn hảo', 'Từ bỏ ảo tưởng cầu toàn và kiên quyết hành động ngay', 'Trì hoãn thêm vài ngày'], 1, 'Trong câu cuối có viết: 停止不切实际的完美主义幻想，果断付诸即刻行动.')]),
    (46, '现代城市中的社区活力', 'Khơi dậy sức sống cộng đồng trong đô thị hiện đại', 'community_building', 'Đô thị & Xã hội', '🏘️', 5, 'Không gian sinh hoạt chung và hoạt động văn hóa giúp kéo gần khoảng cách, gắn kết tình làng nghĩa xóm chốn đô thị.', [('在钢筋水泥构筑的高楼大厦中，紧闭的防盗门往往让对门邻居变得形同陌路。', 'Zài gāngjīn shuǐní gòuzhù de gāolóu-dàshà zhōng, jǐnbì de fángdàomén wǎngwǎng ràng duìmén línjū biàn de xíngtóng-mòlù.', 'Giữa những tòa cao ốc bê tông cốt thép, cánh cửa chống trộm đóng chặt thường khiến hàng xóm đối diện nhà nhau trở nên như người xa lạ.'), ('为了打破这种城市冷漠感，许多社区开始积极打造开放式的公共交往空间与社区花园。', 'Wèile dǎpò zhè zhǒng chéngshì lěngmògǎn, xǔduō shèqū kāishǐ jījí dǎzào kāifàngshì de gōnggòng jiāowǎng kōngjiān yǔ shèqū huāyuán.', 'Nhằm phá vỡ sự thờ ơ lạnh lẽo chốn đô thị này, nhiều khu dân cư bắt đầu tích cực xây dựng các không gian giao lưu công cộng mở và vườn hoa cộng đồng.'), ('周末举办的邻里跳蚤市场、亲子烘焙工坊与志愿植树活动，吸引了各个年龄段居民的热情参与。', 'Zhōumò jǔbàn de lǐnlǐ tiàozǎo shìchǎng, qīnzǐ hōngbèi gōngfāng yǔ zhìyuàn zhíshù huódòng, xīyǐn le gègè niánlíngduàn jūmín de rèqíng cānyù.', 'Chợ phiên đồ cũ, xưởng bánh gia đình và hoạt động trồng cây tình nguyện tổ chức vào cuối tuần đã thu hút sự tham gia nhiệt tình của cư dân mọi lứa tuổi.'), ('在欢声笑语的互动中，陌生人变成了熟络的朋友，彼此之间互帮互助的温暖氛围日益浓厚。', 'Zài huānshēng-xiàoyǔ de hùdòng zhōng, mòshēngrén biànchéng le shúluò de péngyou, bǐcǐ zhījiān hùbāng-hùzhù de wēnnuǎn fēnwéi rìyì nónghòu.', 'Trong những tiếng cười nói rộn rã khi tương tác, người lạ đã trở thành bạn bè quen thân, bầu không khí tương thân tương ái giữa xóm giềng ngày thêm gắn kết.'), ('充满温情与活力的现代社区，不仅提升了居民的归属感，更是构筑和谐社会的坚固基石。', 'Chōngmǎn wēnqíng yǔ huólì de xiàndài shèqū, bùjǐn tíshēng le jūmín de guīshǔgǎn, gèng shì gòuzhù héxié shèhuì de jiāngù jīshí.', 'Một cộng đồng hiện đại ngập tràn hơi ấm và sức sống không chỉ nâng cao cảm giác thuộc về nơi chốn của người dân mà còn là nền tảng vững chắc cho xã hội hài hòa.')], [('Hiện trạng phổ biến trong các khu chung cư cao tầng hiện nay là gì?', ['Mọi người tụ tập hàng ngày', 'Cửa đóng chặt khiến hàng xóm sát vách thành người xa lạ', 'Không ai muốn ở nhà'], 1, 'Trong bài có câu: 紧闭的防盗门往往让对门邻居变得形同陌路.'), ('Các khu dân cư đã làm gì để kết nối người dân với nhau?', ['Xây tường rào cao hơn', 'Tạo không gian công cộng mở, vườn hoa và tổ chức chợ phiên, hoạt động gia đình', 'Phạt tiền người không nói chuyện'], 1, 'Trong câu có viết: 打造开放式的公共交往空间与社区花园，举办跳蚤市场与亲子活动.'), ('Giá trị lớn nhất mà một cộng đồng giàu sức sống mang lại là gì?', ['Làm tăng giá thuê nhà', 'Nâng cao cảm giác gắn bó thuộc về nơi chốn và xây dựng xã hội hài hòa', 'Thu hút nhiều người bán hàng rong'], 1, 'Trong câu cuối có viết: 提升了居民的归属感，更是构筑和谐社会的坚固基石.')]),
    (47, '微塑料污染与海洋生态', 'Ô nhiễm vi nhựa và sự suy thoái sinh thái đại dương', 'ocean_ecology', 'Sinh thái học biển', '🐟', 5, 'Những mảnh vi nhựa vô hình đang xâm nhập chuỗi thức ăn đại dương và quay trở lại đe dọa sức khỏe con người.', [('塑料制品给现代生活带来了极大的便利，但其难以降解的特性也给自然环境带来了沉重包袱。', 'Sùliào zhìpǐn gěi xiàndài shēnghuó dàilái le jídà de biànlì, dàn qí nányǐ jiàngjiě de tèxìng yě gěi zìrán huánjìng dàilái le chénzhòng bāofu.', 'Đồ nhựa đem lại tiện ích khổng lồ cho đời sống hiện đại, nhưng đặc tính khó phân hủy của chúng cũng tạo gánh nặng trĩu nặng cho môi trường tự nhiên.'), ('散落在海洋中的塑料垃圾经过阳光紫外线照射和海浪冲击，逐渐破碎分解为细小的微塑料颗粒。', 'Sǎnlùo zài hǎiyáng zhōng de sùliào lājī jīngguò yángguāng zǐwàixiàn zhàoshè hé hǎilàng chōngjī, zhújiàn pòsuì fēnjiě wéi xìxiǎo de wēisùliào kēlì.', 'Rác thải nhựa trôi nổi trên đại dương qua nắng chiếu tia cực tím và sóng biển đập vỡ dần phân rã thành những hạt vi nhựa li ti.'), ('这些直径小于五毫米的隐形杀手极易被浮游生物、鱼类和贝类误食，从而进入海洋食物链。', "Zhèxiē zhíjìng xiǎoyú wǔ háomǐ de yǐnxíng shāshǒu jí yì bèi fúyóu shēngwù, yúlèi hé bèilèi wùshí, cóng'ér jìnrù hǎiyáng shíwùliàn.", 'Những sát thủ vô hình có đường kính dưới 5 milimet này rất dễ bị sinh vật phù du, cá tôm và sò ốc nuốt nhầm, từ đó thâm nhập vào chuỗi thức ăn đại dương.'), ('微塑料不仅会堵塞海洋生物的消化系统，更会通过海鲜产品的层层富集最终危害人类自身健康。', 'Wēisùliào bùjǐn huì dǔsè hǎiyáng shēngwù de xiāohuà xìtǒng, gèng huì tōngguò hǎixiān chǎnpǐn de céngcéng fùjí zuìzhōng wēihài rénlèi zìshēn jiànkāng.', 'Vi nhựa không chỉ làm tắc nghẽn hệ tiêu hóa của sinh vật biển mà còn tích tụ qua các tầng thủy hải sản để cuối cùng gây hại cho chính sức khỏe con người.'), ('治理塑料污染刻不容缓，推广可降解替代品并加强源头分类回收，是守护蔚蓝海洋的必由之路。', 'Zhìlǐ sùliào wūrǎn kèbùrónghuǎn, tuīguǎng kě jiàngjiě tìdàipǐn bìng jiāqiáng yuántóu fēnlèi huíshōu, shì shǒuhù wèilán hǎiyáng de bìyóuzhīlù.', 'Kiểm soát ô nhiễm nhựa là việc cấp bách không thể chậm trễ; nhân rộng vật liệu thay thế tự phân hủy và tăng cường phân loại thu gom rác tại nguồn là con đường tất yếu bảo vệ đại dương xanh.')], [('Hạt vi nhựa đại dương hình thành từ nguyên nhân nào?', ['Do cá thải ra', 'Rác nhựa biển bị tia cực tím và sóng đập phân rã thành hạt nhỏ', 'Do muối biển kết tinh'], 1, 'Trong bài có câu: 塑料垃圾经过阳光紫外线照射和海浪冲击，逐渐破碎分解为细小的微塑料颗粒.'), ('Hiểm họa của vi nhựa đối với chuỗi thức ăn đại dương là gì?', ['Sinh vật biển nuốt nhầm, gây tắc hệ tiêu hóa và tích tụ vào hải sản con người ăn', 'Làm nước biển ngọt hơn', 'Giúp cá lớn nhanh hơn'], 0, 'Trong câu có viết: 堵塞海洋生物的消化系统，更会通过海鲜产品的层层富集最终危害人类自身健康.'), ('Giải pháp then chốt để ngăn chặn ô nhiễm nhựa biển là gì?', ['Đổ thêm rác ra biển', 'Dùng vật liệu thay thế tự phân hủy và phân loại rác thu gom tại nguồn', 'Ngừng đánh bắt cá'], 1, 'Trong câu cuối có viết: 推广可降解替代品并加强源头分类回收.')]),
    (48, '传统节日的文化凝聚力', 'Sức mạnh gắn kết văn hóa từ các lễ hội truyền thống', 'traditional_festivals', 'Văn hóa & Phong tục', '🏮', 5, 'Đoàn tụ gia đình, ẩm thực đặc trưng và phong tục cổ truyền là sợi dây thiêng liêng kết nối các thế hệ.', [('中国传统节日宛如一部厚重的历史卷轴，承载着数千年来中华民族深沉的情感依恋与文化根脉。', 'Zhōngguó chuántǒng jiérì wǎnrú yí bù hòuzhòng de lìshǐ juànzhóu, chéngzài zhe shù qiān nián lái Zhōnghuá mínzú shēnchén de qínggǎn yīliàn yǔ wénhuà gēnmài.', 'Các ngày lễ truyền thống Trung Hoa tựa như một cuốn trục lịch sử dày dặn, chuyên chở nỗi niềm tình cảm sâu sắc và cội rễ văn hóa ngàn năm của dân tộc.'), ('春节的除夕团聚、端午的龙舟竞渡与中秋的皓月相伴，每一个节日都蕴含着独特的民俗内涵。', 'Chúnjié de chúxī tuánjù, Duānwǔ de lóngzhōu jìngdù yǔ Zhōngqiū de hàoyuè xiāngbàn, měi yí gè jiérì dōu yùnhán zhe dútè de mínsú nèihán.', 'Đoàn tụ đêm trừ tịch ngày Tết Nguyên Đán, đua thuyền rồng dịp Tết Đoan Ngọ và vầng trăng sáng Tết Trung Thu, mỗi ngày lễ đều chứa đựng hàm nghĩa phong tục độc đáo.'), ('无论游子身处何方，每当节令来临，心中那份对故乡与亲人的深切眷恋便会不由自主地升腾。', 'Wúlùn yóuzǐ shēn chǔ hé fāng, měi dāng jiélìng láilín, xīnzhōng nà fèn duì gùxiāng yǔ qīnrén de shēnqiè juànliàn biàn huì bùyóu-zìzhǔ de shēngténg.', 'Bất kể người con xa xứ ở phương trời nào, mỗi khi mùa lễ hội tới, nỗi niềm tha thiết hướng về quê cha đất tổ và người thân trong lòng lại trào dâng vô thức.'), ('围坐在丰盛的年夜饭旁分享过去一年的酸甜苦辣，这种血脉相连的温情能够抚平一切奔波劳碌。', 'Wéizuò zài fēngshèng de niányèfàn páng fēnxiǎng guòqù yì nián de suāntián-kǔlà, zhè zhǒng xuèmài-xiānglián de wēnqíng nénggòu fǔpíng yíqiè bēnbō láolù.', 'Quây quần bên mâm cơm tất niên thịnh soạn sẻ chia những cay đắng ngọt bùi của năm cũ, hơi ấm tình thâm ruột thịt này có thể xoa dịu mọi nhọc nhằn bươn chải.'), ('传承节日文化不仅是温习古老的传统仪式，更是在快速流变的世界中守住我们共同的精神家园。', 'Chuánchéng jiérì wénhuà bùjǐn shì wēnxí gǔlǎo de chuántǒng yíshì, gèng shì zài kuàisù liúbiàn de shìjiè zhōng shǒu zhù wǒmen gòngtóng de jīngshén jiāyuán.', 'Gìn giữ văn hóa lễ hội không chỉ là ôn lại nghi thức truyền thống xưa cũ, mà còn là giữ vững mái nhà tinh thần chung của chúng ta giữa một thế giới biến thiên không ngừng.')], [('Điểm chung thiêng liêng của các ngày lễ truyền thống là gì?', ['Chỉ để nghỉ làm việc', 'Chuyên chở tình cảm gắn kết dân tộc và cội rễ văn hóa qua hàng ngàn năm', 'Bắt buộc phải đi mua sắm'], 1, 'Trong bài có câu: 承载着数千年来中华民族深沉的情感依恋与文化根脉.'), ('Cảm xúc tự nhiên của người con xa xứ mỗi dịp tết đến xuân về là gì?', ['Quên mất quê hương', 'Nỗi niềm nhớ nhung tha thiết hướng về quê hương và gia đình trỗi dậy', 'Không quan tâm'], 1, 'Trong câu có viết: 心中那份对故乡与亲人的深切眷恋便会不由自主地升腾.'), ('Ý nghĩa sâu xa của việc kế thừa văn hóa lễ hội trong thời hiện đại là gì?', ['Giữ vững chốn nương tựa tinh thần chung giữa dòng chảy thế giới biến đổi nhanh chóng', 'Làm lãng phí tiền của', 'Chỉ làm theo hình thức'], 0, 'Trong câu cuối có viết: 在快速流变的世界中守住我们共同的精神家园.')]),
    (49, '科技适老化的人文关怀', 'Sự quan tâm nhân văn trong công nghệ dành cho người cao tuổi', 'silver_tech', 'Công nghệ & Xã hội', '👴', 5, 'Thiết kế giao diện đơn giản, phông chữ lớn và hỗ trợ giọng nói giúp người cao tuổi không bị bỏ lại phía sau thời đại số.', [('移动互联网的高速发展极大地方便了年轻一代，但也给许多老年人带来了难以跨越的数字鸿沟。', 'Yídòng hùliánwǎng de gāosù fāzhǎn jídà de fāngbiàn le niánqīng yídài, dàn yě gěi xǔduō lǎoniánrén dàilái le nányǐ kuàyuè de shùzì hónggōu.', 'Sự phát triển vũ bão của Internet di động đem lại sự tiện lợi vô biên cho người trẻ, nhưng cũng đem lại hố sâu ngăn cách số khó vượt qua cho nhiều người cao tuổi.'), ('面对复杂的手机挂号、扫码支付和在线打车程序，许多老人常常感到无所适从与焦虑无助。', 'Miànduì fùzá de shǒujī guàhào, sǎomǎ zhīfù hé zàixiàn dǎchē chéngxù, xǔduō lǎorén chángcháng gǎndào wúsuǒshìcóng yǔ jiāolǜ wúzhù.', 'Đứng trước những ứng dụng phức tạp như đặt số khám bệnh, quét mã trả tiền và gọi xe trực tuyến, nhiều cụ già thường cảm thấy lúng túng bất an và bất lực.'), ('科技的发展绝不能抛下任何一个群体，推进软件与智能硬件的适老化改造已成为全社会的共识。', 'Kējì de fāzhǎn jué bù néng pāoxià rènhé yí gè qúntǐ, tuījìn ruǎnjiàn yǔ zhìnéng yìngjiàn de shìlǎohuà gǎizào yǐ chéngwéi quán shèhuì de gòngshí.', 'Sự phát triển của công nghệ tuyệt đối không thể bỏ rơi bất kỳ ai, đẩy mạnh cải tạo giao diện phù hợp với người cao tuổi đã trở thành đồng thuận chung toàn xã hội.'), ('推出超大字体界面、简化操作步骤、开发敏锐的语音交互功能，能够大幅降低老年人的使用门槛。', 'Tuīchū chàodà zìtǐ jièmiàn, jiǎnhuà cāozuò bùzhòu, kāifā mǐnruì de yǔyīn jiāohù gōngnéng, nénggòu dàfú jiàngdī lǎoniánrén de shǐyòng ménkǎn.', 'Cho ra mắt giao diện chữ cực lớn, đơn giản hóa các bước thao tác và phát triển tính năng tương tác giọng nói nhạy bén có thể hạ thấp đáng kể rào cản sử dụng của người già.'), ('充满温情的人文关怀，能够让科技的阳光普照到银发一族，让他们同样共享现代文明的成果。', 'Chōngmǎn wēnqíng de rénwén guānhuái, nénggòu ràng kējì de yángguāng pǔzhào dào yínfà-yìzú, ràng tāmen tóngyàng gòngxiǎng xiàndài wénmíng de chéngguǒ.', 'Sự quan tâm nhân văn chan chứa hơi ấm có thể đưa ánh nắng công nghệ sưởi ấm thế hệ tóc bạc, để họ cũng được sẻ chia những thành quả ngọt ngào của văn minh hiện đại.')], [('Khó khăn mà nhiều người cao tuổi gặp phải trong kỷ nguyên số hóa là gì?', ['Không thích dùng điện thoại', 'Hố sâu ngăn cách số khiến họ lúng túng trước các ứng dụng khám bệnh, thanh toán và gọi xe', 'Không có tiền mua điện thoại'], 1, 'Trong bài có câu: 复杂的手机挂号、扫码支付和在线打车程序，许多老人常常感到无所适从.'), ('Các cải tiến công nghệ thân thiện với người già (适老化) bao gồm những gì?', ['Chữ thật nhỏ để chứa nhiều thông tin', 'Phông chữ cực lớn, đơn giản hóa thao tác và tích hợp khẩu lệnh giọng nói', 'Bắt buộc dùng mật khẩu dài phức tạp'], 1, 'Trong câu có viết: 推出超大字体界面、简化操作步骤、开发敏锐的语音交互功能.'), ('Ý nghĩa nhân văn của việc cải tạo công nghệ dành cho người già là gì?', ['Không để người cao tuổi bị bỏ lại phía sau và cùng thụ hưởng quả ngọt văn minh', 'Thu thêm tiền dịch vụ từ người già', 'Buộc người già phải đi học công nghệ'], 0, 'Trong câu cuối có viết: 让科技的阳光普照到银发一族，让他们同样共享现代文明的成果.')]),
    (50, '深空探测与人类探索梦想', 'Thám hiểm không gian sâu và giấc mơ khám phá của nhân loại', 'space_exploration', 'Không gian & Thiên văn', '🚀', 5, 'Từ những bước chân thám hiểm Mặt trăng đến khát vọng sao Hỏa, nhân loại không ngừng vươn tới những chân trời vô tận.', [('浩瀚星空自古以来就激发着人类最深沉的好奇心与无穷无尽的浪漫想象。', 'Hàohàn xīngkōng zìgǔ yǐlái jiù jīfā zhe rénlèi zuì shēnchén de hàoqíxīn yǔ wúqióng-wújìn de làngmàn xiǎngxiàng.', 'Bầu trời sao bao la từ ngàn xưa đã luôn khơi dậy trí tò mò sâu xa nhất cùng trí tưởng tượng lãng mạn vô bờ bến của loài người.'), ('随着现代航天技术的突飞猛进，人类的脚步已经从近地轨道迈向了更为遥远的深空深处。', 'Suízhe xiàndài hángtiān jìshù de tūfēi-měngjìn, rénlèi de jiǎobù yǐjīng cóng jìn-dì guǐdào màixiàng le gèngwéi yáoyuǎn de shēnkōng shēnchù.', 'Cùng với sự tiến bộ thần tốc của kỹ thuật hàng không vũ trụ hiện đại, bước chân nhân loại đã vươn từ quỹ đạo tầm thấp quanh Trái đất tới không gian thăm thẳm xa xôi.'), ('火星探测器的成功着陆并传回高清地貌图像，揭开了这颗红色星球神秘面纱的冰山一角。', 'Huǒxīng tàncèqì de chénggōng zhuólù bìng chuánhuí gāoqīng dìmào túxiàng, jiēkāi le zhè kē hóngsè xīngqiú shénmì miànshā de bīngshān-yìjiǎo.', 'Tàu thăm dò Sao Hỏa hạ cánh thành công và gửi về những hình ảnh địa hình siêu nét đã vén mở một góc tảng băng chìm bí ẩn của hành tinh đỏ.'), ('深空探测不仅有助于揭示太阳系的起源与生命演化之谜，还催生了大量带动地面产业升级的高尖端科技。', 'Shēnkōng tàncè bùjǐn yǒuzhù yú jiēshì Tàiyángxì de qǐyuán yǔ shēngmìng yǎnhuà zhī mǐ, hái cuīshēng le dàliàng dàidòng dìmbiàn chǎnyè shēngjí de gāo-jiānduān kējì.', 'Thám hiểm không gian sâu không chỉ giúp giải mã nguồn gốc hệ Mặt trời và sự tiến hóa của sự sống mà còn khai sinh hàng loạt công nghệ đỉnh cao thúc đẩy công nghiệp dưới mặt đất.'), ('永不停歇的探索脚步，展现了人类勇于跨越认知边界、追求宇宙真理的伟大科学精神。', 'Yǒng bù tíngxiē de tànsuǒ jiǎobù, zhǎnxiàn le rénlèi yǒngyú kuàyuè rènzhī biānjiè, zhuīqiú yǔzhòu zhēnlǐ de wěidà kēxué jīngshén.', 'Bước chân tìm kiếm không bao giờ ngơi nghỉ đã thể hiện tinh thần khoa học vĩ đại của loài người dám vượt qua ranh giới nhận thức để truy tìm chân lý vũ trụ.')], [('Thành tựu mang tính bước ngoặt nào trong thám hiểm Sao Hỏa được nêu?', ['Đã đưa người định cư lên Sao Hỏa', 'Tàu thăm dò hạ cánh thành công và gửi về hình ảnh địa hình siêu nét', 'Tìm thấy thành phố trên Sao Hỏa'], 1, 'Trong bài có câu: 火星探测器的成功着陆并传回高清地貌图像.'), ('Lợi ích kép của việc thám hiểm không gian sâu là gì?', ['Chỉ để giải trí', 'Giải mã nguồn gốc hệ Mặt trời và thúc đẩy công nghệ đỉnh cao phục vụ đời sống mặt đất', 'Lãng phí ngân sách'], 1, 'Trong câu có viết: 揭示太阳系的起源与生命演化之谜，还催生了大量带动地面产业升级的高尖端科技.'), ('Bước chân thám hiểm không gian thể hiện tinh thần cốt lõi nào của nhân loại?', ['Chinh phục vũ lực', 'Dũng cảm vượt qua ranh giới nhận thức và theo đuổi chân lý khoa học', 'Sự tự kiêu'], 1, 'Trong câu cuối có viết: 展现了人类勇于跨越认知边界、追求宇宙真理的伟大科学精神.')]),
]
